/** The `engineering` level of every section that has one, keyed by section id. */
export const ENGINEERING: Readonly<Record<string, LevelContent>> = {"extraction":{"title":"Extraction workflow","blocks":[{"type":"container","kind":"intro","attrs":{},"children":[{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"Every uploaded document moves through six stages — parse, classify, extract, reconcile, verify, reclassify. The pipeline is format-agnostic by design: a single OM may be a text PDF, scanned image, multi-tab Excel, or PowerPoint deck."}]}]},{"type":"container","kind":"stages","attrs":{},"children":[{"type":"container","kind":"stage","attrs":{"n":"1","icon":"FileText"},"children":[{"type":"heading","level":4,"inline":[{"type":"text","value":"Parse"}]},{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"The parser reads raw bytes into text + tables. PDFs use LlamaParse (when configured) with a PyMuPDF fallback. Excel (.xlsx / .xlsm) uses openpyxl; legacy .xls uses xlrd. PowerPoint (.pptx) uses python-pptx. Image-only PDFs without an OCR layer surface as error_kind=no_text so the user gets an actionable retry path."}]}]},{"type":"container","kind":"stage","attrs":{"n":"2","icon":"Sparkles"},"children":[{"type":"heading","level":4,"inline":[{"type":"text","value":"Classify"}]},{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"A Haiku 4.5 Router agent reads the filename plus the first ~2K characters and emits a doc_type: OM, T12, PNL, STR, STR_TREND, CBRE_HORIZONS, PNL_BENCHMARK, RENT_ROLL, MARKET_STUDY, ROOM_MIX, or CONTRACT. A filename heuristic provides the fallback when the Router is unsure. Files dropped in the “Drop everything here” zone carry no analyst tag, so the Router’s doc_type is the category; the Data Room marks them “Classified automatically — confirm” until the analyst confirms or reclassifies. Accepted formats: PDF, Excel (.xlsx / .xlsm / .xls), CSV, Word (.docx) and PowerPoint (.pptx) — Google Sheets / Slides via File → Download → Excel / PowerPoint."}]}]},{"type":"container","kind":"stage","attrs":{"n":"3","icon":"BarChart3"},"children":[{"type":"heading","level":4,"inline":[{"type":"text","value":"Extract"}]},{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"A Sonnet 4.6 Extractor agent loads a per-doc-type schema (apps/worker/app/agents/extraction_schemas/) and pulls every grounded number, identifier, and date into a flat list of typed ExtractionField rows: field_name, value, unit, source_page, confidence, raw_text. Anything not grounded in the source is dropped."}]}]},{"type":"container","kind":"stage","attrs":{"n":"4","icon":"Database"},"children":[{"type":"heading","level":4,"inline":[{"type":"text","value":"Reconcile"}]},{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"When a P&L-family workbook (T-12 / P&L) carries its own USALI Summary sheet, a deterministic reconciler reads that sheet by row label — Rooms, Food & Beverage, Other Operated, Total Revenues, the departmental and undistributed expense lines, GOP, EBITDA — and takes the annual column that sums the twelve months; any canonical USALI total the extractor read from a department or outlet sheet that differs from the Summary by more than 5% is replaced with the Summary value, marked reconciled with the original value and source kept beside it. A second per-deal check caps a statement's F&B, Rooms or Total revenue at 50% confidence when it is below a quarter of the deal's other full-period statements for the same line, so a single-outlet GL line can never pass as the department total unreviewed."}]}]},{"type":"container","kind":"stage","attrs":{"n":"5","icon":"Link2"},"children":[{"type":"heading","level":4,"inline":[{"type":"text","value":"Verify"}]},{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"A Critic pass re-reads each cited number against the parser cache. Verified fields get a 0.98 confidence floor; mismatches drop to 0.50. The downstream UI surfaces this as the field-level confidence badge."}]}]},{"type":"container","kind":"stage","attrs":{"n":"6","icon":"ArrowRight"},"children":[{"type":"heading","level":4,"inline":[{"type":"text","value":"Reclassify"}]},{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"A post-extraction reclassifier reads p_and_l_usali.period_type off the extracted fields and narrows broad PNL/T12 classifications into PNL_MONTHLY, PNL_YTD, or T12. This is why a single-month upload no longer outranks an annual T-12 in the engine actuals loaders."}]}]}]},{"type":"container","kind":"card","attrs":{},"children":[{"type":"heading","level":4,"inline":[{"type":"text","value":"Stuck jobs time out; they never spin forever"}]},{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"Every status change on a document is time-stamped ("},{"type":"code","value":"status_changed_at"},{"type":"text","value":"), and every stage log line carries the job id that drove it. A worker-side watchdog sweeps at startup and once a minute: any document still Parsing, Classifying or Extracting with no status change for "},{"type":"code","value":"EXTRACTION_STUCK_MINUTES"},{"type":"text","value":" (default 30) is marked Failed with "},{"type":"code","value":"error_kind=timeout"},{"type":"text","value":", a message naming the stage and the elapsed time, and an audit entry ("},{"type":"code","value":"document.extraction_timed_out"},{"type":"text","value":"). The Data Room shows it as “Timed out after N min — Retry”. A job that dies with an exception — including a worker restart mid-extraction — is failed on the spot ("},{"type":"code","value":"error_kind=cancelled"},{"type":"text","value":") rather than left in flight. Retry on a document that is still moving and younger than the threshold is refused, so two pipelines never run on one file; once the threshold has passed, Retry (or a forced re-extraction) is accepted and audited. Nothing is wrong with the file in either case — the same bytes run again from the start."}]}]},{"type":"container","kind":"card","attrs":{},"children":[{"type":"heading","level":4,"inline":[{"type":"text","value":"Re-running extraction"}]},{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"Any document that has finished — extracted or failed — can be extracted again from the Data Room: the re-run icon on its row, or “Re-run extraction for all documents” in the coverage header. A confirm step says what will happen first. An extracted document goes back through "},{"type":"code","value":"POST …/extract"},{"type":"text","value":"; a failed one through "},{"type":"code","value":"POST …/reprocess"},{"type":"text","value":", which re-parses it from the stored file. Either way the run is fresh under the current pipeline version: it never reuses the content-hash cache or a sibling template mapping, so a pipeline change actually reaches documents uploaded before it. Each request is audited as "},{"type":"code","value":"document.re_extract_requested"},{"type":"text","value":" with the person who asked, the previous status and the pipeline version. A document still in the pipeline and younger than "},{"type":"code","value":"EXTRACTION_STUCK_MINUTES"},{"type":"text","value":" is refused, and the action is greyed out with that reason meanwhile. The re-run writes a new extraction result and every reader takes the newest one. Field reviews made on the previous result (accepted, edited or rejected values) are not carried over, so anything the new result flags needs reviewing again. The previous result stays in the database as history. The document type and year the analyst set are kept as their input, and a disagreement with the new read is flagged for confirmation, as on first extraction. Deal-level model overrides and their justification notes live on the deal and are untouched. Progress shows through the normal status polling, and when the last document in the re-run finishes, the model runs once."}]}]},{"type":"container","kind":"card","attrs":{"testid":"methodology-duplicate-deal"},"children":[{"type":"heading","level":4,"inline":[{"type":"text","value":"Duplicating a deal before re-testing"}]},{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"Because a re-extraction does not carry field reviews over, “Duplicate deal” in the project header menu makes a working copy first ("},{"type":"code","value":"POST /deals/{id}/duplicate"},{"type":"text","value":"). The copy lands in the same workspace as “<name> (copy YYYY-MM-DD)” and carries the deal details, every model override with its justification note, the scenarios, and every document with its latest extraction result, including the fields the analyst accepted, edited or rejected, the document type and year the analyst set, and the subtype. The documents point at the same stored files; nothing is uploaded again. P&L cell comments are a per-copy choice: the confirm dialog's “Also copy P&L cell comments” box is off by default, and only when it is ticked do the comment threads come along, each marked “[Copied from <deal>]” and carrying the source deal's id, with their cell references re-pointed at the copied documents; otherwise the response lists them as not copied. Model runs are not copied, and neither is the activity history: the copy shows no results until the model is run on it, and its history starts with one "},{"type":"code","value":"deal.duplicated"},{"type":"text","value":" entry naming the source deal. Duplicating is refused while a document is still being processed. The original deal is not changed, and deleting the copy or one of its documents never removes a file the original still uses."}]}]}]},"projection":{"title":"Projection methodology","blocks":[{"type":"container","kind":"intro","attrs":{},"children":[{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"Year-1 anchors source from the deal's actual extracted data when available; out-years compound from the un-displaced baseline so a heavy PIP doesn't permanently depress the curve. The full precedence chain by metric:"}]}]},{"type":"container","kind":"card","attrs":{},"children":[{"type":"heading","level":4,"inline":[{"type":"text","value":"Year-1 Occupancy + ADR"}]},{"type":"container","kind":"chain","attrs":{},"children":[{"type":"list","ordered":true,"attrs":{},"items":[{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Analyst override"}]},{"type":"text","value":" — Set via the Overview inline editor — wins over every other source."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"T-12 actual"}]},{"type":"text","value":" — Extracted from the deal's primary financial statement — the same document the Data Room badges as Primary source (full-year statements first, most recent period first, a T-12 ahead of a calendar-year P&L of the same year)."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"CBRE Horizons Y1 forecast"}]},{"type":"text","value":" — When the deal has no T-12 but a CBRE Horizons report is uploaded, the segmented Y1 forecast feeds the anchor."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Fondok platform default"}]},{"type":"text","value":" — Last-resort fallback used only on deals with no extracted data. Surfaced as a Seed badge."}]}]}]}]},{"type":"container","kind":"card","attrs":{},"children":[{"type":"heading","level":4,"inline":[{"type":"text","value":"The projection calendar, and what \"Base Year\" means"}]},{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"The revenue engine projects "},{"type":"strong","children":[{"type":"text","value":"ordinals"}]},{"type":"text","value":" — operating year 1 through the hold period — not calendar years. The calendar is derived in one place: the "},{"type":"strong","children":[{"type":"text","value":"acquisition close date"}]},{"type":"text","value":" on the deal, the same date the transaction timeline is built from. Operating Year 1 is the calendar year containing the first operating month (close + one month), so a 30 September 2025 close projects Year 1 in 2025 and a 15 December 2025 close projects it in 2026. Every later column is that year plus one."}]},{"type":"paragraph","attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"With no acquisition close date the statement prints no year at all"}]},{"type":"text","value":" — the column shows its label and a dash. It never falls back to the wall clock or to the year a document happened to be extracted from; a guessed year is a fabricated number."}]},{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"The first column is labelled "},{"type":"strong","children":[{"type":"text","value":"Base year (Year 1)"}]},{"type":"text","value":" because that is exactly what it is: "},{"type":"code","value":"revenue.years[0]"},{"type":"text","value":" IS the model's first operating year. It is the value the returns engine consumes as "},{"type":"code","value":"year_one_noi"},{"type":"text","value":" and the value the Cash Flow statement labels \"Year 1\". The P&L used to call it \"Base Year\" and then label the NEXT column \"Year 1\", which put every column a year ahead of its own label. The labels were corrected; the engine was not re-indexed, so no figure moved. There is no separate pre-close base year in the model today."}]},{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"The horizon is "},{"type":"strong","children":[{"type":"text","value":"hold period + 1"}]},{"type":"text","value":" columns. The extra column is the "},{"type":"strong","children":[{"type":"text","value":"Exit Year"}]},{"type":"text","value":", and it is display-only: it carries the forward 12-month NOI the reversion is valued on and a dash on every other line. Year hold+1 is deliberately NOT run through the expense waterfall — see the exit-valuation note below."}]}]},{"type":"container","kind":"card","attrs":{"testid":"methodology-line-methods"},"children":[{"type":"heading","level":4,"inline":[{"type":"text","value":"Per-line expense projection methods"}]},{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"Eight expense lines can be re-driven one at a time from the method chip on their Future P&L row: Rooms, F&B and Other Operated departmental expense, and A&G, IT & Telecom, Sales & Marketing, Property Operations and Utilities. Management fee, FF&E reserve and fixed charges keep their own drivers. The four methods are "},{"type":"strong","children":[{"type":"text","value":"Growth"}]},{"type":"text","value":" (Year 1 grown each year; blank = the model expense inflation), "},{"type":"strong","children":[{"type":"text","value":"% of revenue"}]},{"type":"text","value":" (the department's own revenue for departmental lines, total revenue for undistributed lines), "},{"type":"strong","children":[{"type":"text","value":"POR"}]},{"type":"text","value":" (dollars per occupied room) and "},{"type":"strong","children":[{"type":"text","value":"PAR"}]},{"type":"text","value":" (dollars per available room)."}]},{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"A method picked without a value holds the line's own Year-1 ratio, so no benchmark number is introduced. POR and PAR need the key count; without it the line stays on its default and says why. A line nobody has touched runs exactly as before, and the expense engine reports the active method and value for every line ("},{"type":"code","value":"expense.line_methods"},{"type":"text","value":"). A method change needs a justification note like any other override. The Future P&L Excel export lists every line's method and value on its Assumptions sheet, and an edited workbook re-imports through the same preview and note rule. Changing a method there without a new value drops the old value, because its units belonged to the old method."}]},{"type":"paragraph","attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Operating model."}]},{"type":"text","value":" The new-deal wizard records whether the hotel is owner-operated, third-party managed or brand-managed. The Overview shows it and the Future P&L shows it next to the management fee. It moves no number: the fee check is the general USALI 2–6% of total revenue range for every operating model, and nothing below changes the management fee assumption — the analyst sets it."}]},{"type":"paragraph","attrs":{"testid":"methodology-incentive-fee"},"inline":[{"type":"strong","children":[{"type":"text","value":"Base vs incentive management fee."}]},{"type":"text","value":" The management fee ("},{"type":"code","value":"mgmt_fee_pct"},{"type":"text","value":") is the "},{"type":"em","children":[{"type":"text","value":"base"}]},{"type":"text","value":" fee: a share of each year's total revenue (a Year-1 T-12 management fee, where extracted, is used as-is). The "},{"type":"em","children":[{"type":"text","value":"Incentive fee"}]},{"type":"text","value":" beside it on the Future P&L Assumptions panel ("},{"type":"code","value":"incentive_mgmt_fee_pct_of_gop"},{"type":"text","value":") is opt-in and blank by default — blank means no incentive fee is modelled and every number is exactly what it was without it. When set, each year's incentive fee is "},{"type":"code","value":"max(0, GOP − base fee) × rate"},{"type":"text","value":": a share of GOP after the base fee, never negative, so a year whose GOP does not cover the base fee earns the operator nothing. No owner's-priority hurdle is modelled; the rate applies to all GOP after the base fee. The fee is deducted between the base fee and NOI, so it lowers both NOI bases and everything downstream (debt coverage, the exit value, returns). It appears as its own "},{"type":"em","children":[{"type":"text","value":"Incentive management fee"}]},{"type":"text","value":" row on the Future P&L (only when set), with its own trace ("},{"type":"code","value":"expense.years[].incentive_mgmt_fee"},{"type":"text","value":"), and on the Excel export's Assumptions sheet, which re-imports it. Setting it needs a justification note like any other override. It applies mostly to third-party and brand-managed hotels."}]},{"type":"container","kind":"box","attrs":{"testid":"methodology-mgmt-fee-guidance"},"children":[{"type":"heading","level":5,"inline":[{"type":"text","value":"Management fee — directional guidance by operating model"}]},{"type":"paragraph","attrs":{},"inline":[{"type":"em","children":[{"type":"slot","name":"mgmt-fee-disclaimer"}]},{"type":"text","value":" The same text is shown beside the management fee on the Future P&L."}]},{"type":"slot","name":"mgmt-fee-guidance"}]}]},{"type":"container","kind":"card","attrs":{"testid":"methodology-future-pl"},"children":[{"type":"heading","level":4,"inline":[{"type":"text","value":"Reading the Future P&L"}]},{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"The tab is "},{"type":"strong","children":[{"type":"text","value":"P&L"}]},{"type":"text","value":", with two views: "},{"type":"strong","children":[{"type":"text","value":"Historical P&L"}]},{"type":"text","value":" — the normalized operating actuals, one column per extracted statement — and "},{"type":"strong","children":[{"type":"text","value":"Future P&L"}]},{"type":"text","value":", the forward business plan the returns are built on. The Overview carries a compact "},{"type":"em","children":[{"type":"text","value":"Future P&L · Years 1–5"}]},{"type":"text","value":" card (Total Revenue and NOI before the FF&E reserve per year, read from "},{"type":"code","value":"revenue.years"},{"type":"text","value":" and "},{"type":"code","value":"expense.years"},{"type":"text","value":") with a \"→ P&L\" link; it shows a dash until the engines have run."}]},{"type":"paragraph","attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Column headers."}]},{"type":"text","value":" Every projected column reads "},{"type":"code","value":"Year N · 2026"},{"type":"text","value":" — the ordinal and the calendar year the revenue engine derived from the acquisition close date. With no close date the header is the bare "},{"type":"code","value":"Year N"},{"type":"text","value":" and a one-line note says to set the acquisition date on CAPEX; no year is ever guessed. The first column reads "},{"type":"code","value":"Base year (Year 1) · 2025"},{"type":"text","value":", and its basis line names the period of the primary financial statement (\"T12 Mar 2025\", exactly as the Historical P&L column heads it) when the Data Room has flagged one and its extraction states the period; otherwise that line is a dash."}]},{"type":"paragraph","attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Click-through."}]},{"type":"text","value":" Every projected Occupancy, ADR, RevPAR and statement amount opens the value-lineage drawer for its engine field ("},{"type":"code","value":"revenue.years[i].adr"},{"type":"text","value":", "},{"type":"code","value":"expense.years[i].noi_institutional"},{"type":"text","value":", …), which walks the inputs the engine asserted — starting value, growth, index or penetration where present — down to the source rows. When the lineage record carries no walk for a cell the drawer says \"No trace available for this cell.\"; the app never prints a formula it did not record."}]},{"type":"paragraph","attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Ratios."}]},{"type":"text","value":" The \"% Rev\" sub-column (the "},{"type":"em","children":[{"type":"text","value":"Show %"}]},{"type":"text","value":" switch, on by default) is each line as a share of that year's Total Revenue. Departmental expense lines follow the USALI convention instead — Rooms expense ÷ Rooms revenue, F&B expense ÷ F&B revenue, Other Operated expense ÷ Other Operated revenue — and are marked "},{"type":"em","children":[{"type":"text","value":"dept"}]},{"type":"text","value":". Every ratio is computed from the same engine year values the Amount cells print."}]},{"type":"paragraph","attrs":{"testid":"benchmark-column-methodology"},"inline":[{"type":"strong","children":[{"type":"text","value":"Benchmark column."}]},{"type":"text","value":" When the deal carries a P&L benchmark report (CBRE Benchmarker / \"Trends in the Hotel Industry\" / HotStats, uploaded in the Comp Set / Market slot), the Base-year column group gains a "},{"type":"em","children":[{"type":"text","value":"Benchmark"}]},{"type":"text","value":" sub-column (the "},{"type":"em","children":[{"type":"text","value":"Benchmark"}]},{"type":"text","value":" switch, on by default and remembered per device). Thirteen lines are mapped — Rooms, F&B and Other Operated departmental expense; A&G, IT, Sales & Marketing, Property Operations, Utilities; GOP; Management Fees; Property Taxes, Insurance and Rent. Each prints the comp-set ratio on the row's own basis (departmental expense ÷ that department's revenue, everything else ÷ total revenue — the same basis as its % Rev cell, served by "},{"type":"code","value":"GET /deals/{id}/market-data · pnl_benchmark.categories"},{"type":"text","value":") and the model's Year-1 ratio minus it, in points. The colour marks direction only — model above or below the benchmark — never a verdict; no threshold is invented. A line the report did not publish, or a row with no benchmark mapping, shows a dash with the reason. Its tooltip names the benchmark line, the peer-set size, POR / PAR, the source document and how the ratio was derived (line total ÷ revenue total, PAR ÷ PAR, as printed, or the legacy summary). Without a benchmark the column does not exist. The fuller comparison (model vs benchmark, POR, PAR for every mapped line) stays under the collapsed "},{"type":"em","children":[{"type":"text","value":"Benchmark detail"}]},{"type":"text","value":" disclosure below the table, and the Excel export carries the same ratios as a read-only "},{"type":"em","children":[{"type":"text","value":"Benchmark %"}]},{"type":"text","value":" column that import ignores."}]},{"type":"paragraph","attrs":{"testid":"benchmark-suggestions-methodology"},"inline":[{"type":"strong","children":[{"type":"text","value":"Benchmarks are suggestions."}]},{"type":"text","value":" A CBRE / HotStats benchmark never flows into the model on its own. For four assumptions the worker turns the report into a suggestion ("},{"type":"code","value":"GET /deals/{id}/benchmark-suggestions"},{"type":"text","value":"): the Rooms and F&B departmental ratios (the same ratio the Benchmark column prints for that row, or the report's summary "},{"type":"code","value":"rooms_dept_pct"},{"type":"text","value":" / 1 − "},{"type":"code","value":"fb_dept_margin"},{"type":"text","value":" when it has no line detail), the management fee (the Management Fees line, else "},{"type":"code","value":"mgmt_fee_pct"},{"type":"text","value":") and the FF&E reserve ("},{"type":"code","value":"ffe_reserve_pct"},{"type":"text","value":"). Each suggestion lists the value, the benchmark line, the peer-set size, the document and page, and the value the model is on now with its source. A departmental ratio outside 0–100%, or a fee or reserve outside 0–10%, is not suggested. Until the analyst acts, each assumption keeps its existing source: your portfolio P&L ratio when one is on the deal, else the platform default (the hotel-type departmental ratio, a 3% management fee, a 4% FF&E reserve), labelled as such. "},{"type":"em","children":[{"type":"text","value":"Apply benchmark"}]},{"type":"text","value":" sits on the Rooms, F&B and Management Fees rows of the Benchmark column and beside the "},{"type":"em","children":[{"type":"text","value":"Management fee"}]},{"type":"text","value":" and "},{"type":"em","children":[{"type":"text","value":"FF&E reserve"}]},{"type":"text","value":" inputs in the Assumptions panel's Deal economics card (the reserve input shows the value the model is on — your override, else the loader's value — and takes an override with a note like the fee). It opens a justification note prefilled as \"Applied CBRE benchmark <line> <value> from <document> p.<page>\", which you can edit. Saving writes an ordinary analyst override with that note and re-runs the model; if the save fails the note stays open for you to retry. From then on the value reads as an analyst override, and the note travels with it like any other override. Approval is reversible: once an override exists on the management fee or the FF&E reserve, "},{"type":"em","children":[{"type":"text","value":"Reset to source"}]},{"type":"text","value":" beside that input removes it, so the portfolio P&L ratio or the platform default drives the model again, and re-runs. Precedence is otherwise unchanged. A Year-1 amount the T-12 states is still used as stated. The applied ratio drives what the T-12 does not state: a departmental line the T-12 leaves out, and the management fee and FF&E reserve in every year after Year 1, where each year is that year's total revenue × the ratio."}]},{"type":"paragraph","attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"The waterfall below Total Revenue"}]},{"type":"text","value":" runs GOP → Management Fees (→ Incentive management fee, when one is modelled) → EBITDA → Fixed Charges (property taxes, insurance, equipment lease / rent, other) → "},{"type":"strong","children":[{"type":"text","value":"NOI (before FF&E reserve)"}]},{"type":"text","value":" → FF&E Reserve → "},{"type":"strong","children":[{"type":"text","value":"Cash NOI (after FF&E reserve)"}]},{"type":"text","value":", each line labelled with its basis. The reserve sits between the two NOI lines because that is where the expense engine deducts it ("},{"type":"code","value":"noi_institutional = gop − mgmt_fee − incentive_mgmt_fee − fixed"},{"type":"text","value":", the incentive term zero when none is modelled; "},{"type":"code","value":"noi = noi_institutional − ffe_reserve"},{"type":"text","value":")."}]},{"type":"paragraph","attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Numbers."}]},{"type":"text","value":" Nothing on the tab renders in scientific notation; ADR and RevPAR print to the cent; every amount cell carries its full value — thousands separators and cents — in its tooltip. Year columns are separated by a rule and an alternating tint, and both views scroll horizontally behind a persistent scrollbar with a \"N more years →\" cue whenever columns sit off-screen."}]}]},{"type":"container","kind":"card","attrs":{},"children":[{"type":"heading","level":4,"inline":[{"type":"text","value":"The Stabilization Year"}]},{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"\"Stabilized\" names one projection year, and every stabilized figure on every screen — Stabilized Occupancy, ADR, Revenue, NOI, NOI Margin, Yield on Cost, the IC memo's scenario summary and Scenario Analysis' comparison row — is read from "},{"type":"em","children":[{"type":"text","value":"that"}]},{"type":"text","value":" year. It is published as a single block by the expense engine, so two surfaces cannot resolve it differently."}]},{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"The stabilization year defaults to "},{"type":"strong","children":[{"type":"text","value":"Year 3 of operations"}]},{"type":"text","value":" (badged \"Default — confirm\"); on a hold that ends sooner it is the last projected year, and the card says so. The analyst can override it in P&L → Future P&L → Assumptions (badged \"Analyst override\"; re-saving the default unchanged is not an override), and the same default year drives the Financing tab's stabilized DSCR and debt yield. The year in which occupancy first reaches the stabilized assumption (or NOI growth settles) is still shown beneath it as a "},{"type":"em","children":[{"type":"text","value":"model-detected"}]},{"type":"text","value":" hint, but it never selects the year — and stabilized NOI (that year's operating NOI) is a separate figure from the exit NOI the sale is capitalised on."}]},{"type":"paragraph","attrs":{"testid":"methodology-stabilization-anchor"},"inline":[{"type":"strong","children":[{"type":"text","value":"What Year 3 counts from."}]},{"type":"text","value":" With no reopening date the default counts from the "},{"type":"strong","children":[{"type":"text","value":"acquisition close"}]},{"type":"text","value":": projection Year 1 is the first operating year after close, so the default is projection Year 3 and the Overview reads \"Year 3 after close\". For a "},{"type":"strong","children":[{"type":"text","value":"material repositioning or re-flag"}]},{"type":"text","value":" the analyst sets the "},{"type":"strong","children":[{"type":"text","value":"reopening / re-flag date"}]},{"type":"text","value":" on the Overview's Investment Profile card (stored on the deal as "},{"type":"code","value":"reopening_date"},{"type":"text","value":"; a plain deal field, no justification note). The default then counts Year 3 from the "},{"type":"em","children":[{"type":"text","value":"first full operating year after reopening"}]},{"type":"text","value":" — a hotel reopening in March 2027 has 2028 as its first full year, so Year 3 is 2030 — placed on the projection through the same calendar the Future P&L column headers use, and the Overview and Future P&L read \"Year 3 after reopening (Mar 2027)\" (source "},{"type":"code","value":"default_year_3_reopening"},{"type":"text","value":"). A reopening date Fondok cannot place — no acquisition close date to derive the calendar, or a reopening whose Year 3 precedes the projection — keeps the close anchor and says why; it never guesses. The second case is Sam's MVP fallback (decision #7, 2026-10-15): the stabilization year is measured from the acquisition close, and the exception is stated in plain sight wherever the anchor is shown — a notice on the Overview's Stabilization section, the Stabilization Anchor row, the reopening-date field, and the Future P&L Stabilization Year note all read \"Exception: Year 3 after the reopening date (Jun 2019) falls before the first projected year, so stabilization is measured from the acquisition close instead.\" The anchor caption — the stabilized year with the anchor it counts from, \"Year 3 after close (default)\" or \"Year 6 — Year 3 after reopening (Mar 2027) (default)\", with that exception note when the fallback applies — appears wherever a stabilized figure is printed: the Overview's Stabilization section, the Future P&L's Stabilization Year note, CAPEX's Exit NOI basis row when the basis is Stabilized NOI, Financing's stabilized Debt Yield and DSCR cards, and Returns' Yield on Cost. Stabilized NOI stays a separate figure from exit NOI: the Overview prints \"Stabilized NOI\" (the stabilized year's NOI before the FF&E reserve) in its Stabilization section and \"Exit NOI (<basis and period>)\" in its Exit section, and Returns' Yield on Cost names \"Stabilized NOI (Year N, before FF&E reserve)\" while its Exit Value names the exit NOI it capitalises (\"Exit NOI (<period>)\", or forward NOI on an older run) — never one number under both labels. The analyst's override wins over either anchor, and the debt engine's stabilized DSCR and debt yield follow the same resolved year."}]},{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"The Stabilization Year is a "},{"type":"strong","children":[{"type":"text","value":"reporting"}]},{"type":"text","value":" assumption: it selects which projected year the stabilized figures are read from. It moves no cash flow. Setting or changing it leaves the gross sale price, the levered and unlevered IRRs, the equity multiple and the terminal NOI bit-identical — there is a regression test that asserts exactly that. When no year resolves, every stabilized figure renders as a dash with a reason; none of them falls back to another year."}]}]},{"type":"container","kind":"card","attrs":{},"children":[{"type":"heading","level":4,"inline":[{"type":"text","value":"What the exit is valued on"}]},{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"The reversion capitalises the "},{"type":"strong","children":[{"type":"text","value":"forward 12-month Cash NOI"}]},{"type":"text","value":" — the after-FF&E-reserve basis — at the exit cap rate. That forward figure is the last modelled hold year's Cash NOI grown at the RevPAR growth rate; it is an extrapolation, not an operating year projected through the expense waterfall, and the Exit Year column says so by showing its formula and nothing else. An analyst can switch the exit basis ("},{"type":"code","value":"exit_noi_basis"},{"type":"text","value":") to "},{"type":"strong","children":[{"type":"text","value":"stabilized"}]},{"type":"text","value":": the stabilized year's Cash NOI (the analyst's stabilization year, else the derived one) grown at the same rate to the exit year, or the exit year's own NOI when stabilization falls after the exit. Returns names the basis it ran on — e.g. \"Forward 12-month NOI (Year 6)\" or \"Stabilized NOI (Year 3, grown to Year 5)\" — and a "},{"type":"code","value":"terminal_noi_override"},{"type":"text","value":" still beats either basis."}]},{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"This matters because the entry cap rate is struck on NOI "},{"type":"em","children":[{"type":"text","value":"before"}]},{"type":"text","value":" the reserve while the exit is struck on Cash NOI "},{"type":"em","children":[{"type":"text","value":"after"}]},{"type":"text","value":" it. Both are defensible conventions and Fondok keeps both, but it names each one wherever it prints it — the Overview's Exit row reads \"Exit NOI (forward 12-month, after FF&E reserve)\" and the Future P&L row \"Forward 12-Month Cash NOI (after FF&E reserve)\", never a bare \"NOI\". Modelling a real year hold+1 through the waterfall instead would move the gross sale price, both IRRs and the equity multiple on every persisted deal; that is a deliberate post-MVP decision, not an oversight."}]},{"type":"paragraph","attrs":{"testid":"exit-noi-basis-methodology"},"inline":[{"type":"strong","children":[{"type":"text","value":"Exit NOI basis."}]},{"type":"text","value":" Forward 12-month NOI is the default. An analyst can switch the basis to "},{"type":"strong","children":[{"type":"text","value":"Stabilized NOI"}]},{"type":"text","value":" on CAPEX → Exit / Reversion: the reversion then capitalises the stabilized year's NOI grown to exit instead. An analyst-entered terminal NOI override beats both bases. Wherever the Exit NOI is printed, its label names the basis and the period it was taken on, as the run reports them ("},{"type":"code","value":"returns.exit_noi_period_label"},{"type":"text","value":")."}]}]},{"type":"container","kind":"card","attrs":{},"children":[{"type":"heading","level":4,"inline":[{"type":"text","value":"Year-1 renovation displacement"}]},{"type":"paragraph","attrs":{"testid":"methodology-displacement-explicit-only"},"inline":[{"type":"strong","children":[{"type":"text","value":"Only explicit assumptions displace Year 1."}]},{"type":"text","value":" A renovation budget is a capital cost: it flows into Sources & Uses and the equity requirement, and it never reduces Year-1 occupancy or ADR on its own — whether the analyst typed it in, the OM's broker pro forma states it, or a PIP / CapEx document does. Year 1 is displaced only when the analyst sets an explicit assumption: "},{"type":"strong","children":[{"type":"text","value":"Y1 Rooms Offline (Occupancy Displacement)"}]},{"type":"text","value":" ("},{"type":"code","value":"y1_occupancy_displacement_pct"},{"type":"text","value":") and "},{"type":"strong","children":[{"type":"text","value":"Y1 Rate (ADR) Displacement"}]},{"type":"text","value":" ("},{"type":"code","value":"y1_adr_displacement_pct"},{"type":"text","value":") on CAPEX → Initial Renovation / PIP, each 0–50% with a justification note; a "},{"type":"strong","children":[{"type":"text","value":"renovation displacement schedule"}]},{"type":"text","value":" (below — explicit timing, rooms offline and rate discount per period, the lever Sam asked for); or a structured PIP closure schedule (closure strategy, % of rooms offline by month, brand recovery curve). All default to off. No extraction schema reads a rooms-offline or rate-displacement figure off a document today — a PIP / CapEx document's spend timing is dollars by year, not rooms out of service — so nothing extracted sets them. Years the renovation does not fall in compound from the un-displaced baseline, so a renovation affects only the year it is modelled in."}]},{"type":"paragraph","attrs":{"testid":"methodology-displacement-schedule"},"inline":[{"type":"strong","children":[{"type":"text","value":"The renovation displacement schedule."}]},{"type":"text","value":" CAPEX → Initial Renovation / PIP → "},{"type":"strong","children":[{"type":"text","value":"Renovation displacement schedule"}]},{"type":"text","value":" takes a list of periods ("},{"type":"code","value":"renovation_displacement_schedule"},{"type":"text","value":", one override with one justification note; also rows on the Future P&L Excel Assumptions sheet), each with a first and last month counted from the acquisition close (1 = the first operating month, inclusive), the share of rooms offline and the rate discount on the rooms that keep selling. The revenue engine turns it into one occupancy factor and one ADR factor per model year: model year "},{"type":"em","children":[{"type":"text","value":"y"}]},{"type":"text","value":" is months 12("},{"type":"em","children":[{"type":"text","value":"y"}]},{"type":"text","value":"−1)+1 to 12"},{"type":"em","children":[{"type":"text","value":" y"}]},{"type":"text","value":" and every month weighs 1/12 (calendar day counts are ignored); in each month the rooms offline across the periods covering it add up (capped at 100%), as do the rate discounts; "},{"type":"strong","children":[{"type":"text","value":"occupancy factor"}]},{"type":"text","value":" = the 12-month average of (1 − rooms offline), applied to the year's occupancy on the full inventory, so taking rooms offline reads as lower occupancy and RevPAR still equals rooms revenue ÷ rooms available; "},{"type":"strong","children":[{"type":"text","value":"ADR factor"}]},{"type":"text","value":" = the open-room-weighted average of (1 − rate discount), applied to the year's ADR, so the discount only touches the rooms that actually sold. Six months at 25% offline and 10% off therefore give Year 1 occupancy × 0.875 and ADR × 0.957 — the same as summing twelve months of open share × discounted rate, one calculation applied to the two lines rather than two deductions. A period in months 13–18 displaces Year 2 the same way while Year 2's base still compounds from the un-displaced Year 1. When a schedule is set it is the "},{"type":"strong","children":[{"type":"text","value":"only"}]},{"type":"text","value":" renovation impact applied: the Y1 displacement percentages and any PIP closure schedule are not applied on top (the status line says so), so nothing is ever counted twice. With no period entered — the default — every deal runs exactly as before, and the renovation budget alone never moves a single operating line."}]},{"type":"paragraph","attrs":{"testid":"methodology-displacement-status"},"inline":[{"type":"strong","children":[{"type":"text","value":"The model says what it decided."}]},{"type":"text","value":" The worker reports a displacement status ("},{"type":"code","value":"assumption_sources.displacement_status"},{"type":"text","value":") once every override is applied, and the CAPEX tab's Renovation Budget row and the Future P&L Year-1 basis line print it verbatim — the Future P&L line links to the CAPEX inputs. With no explicit assumption it reads \"No Year-1 renovation impact — set rooms offline / rate displacement assumptions to model one\" (adding that the renovation budget is a capital cost only when one is set); with one it reads \"Year-1 renovation impact on — analyst-set displacement assumptions (occupancy −10%, ADR −5%)\", the percentages being the ones the revenue engine applies; with a renovation displacement schedule it reads \"Renovation impact on — analyst-set displacement schedule (months 1–6: 25% rooms offline, 10% rate discount). Year 1: occupancy ×0.875, ADR ×0.957\" and, when the Y1 percentages are also set, adds that the schedule wins and they are not applied on top; or it names the analyst-set PIP closure schedule. Until October 2026 a deal-specific budget over $5,000 per key automatically cut Year-1 occupancy 15% and ADR 8%; that budget-amount heuristic has been removed."}]}]},{"type":"container","kind":"card","attrs":{"testid":"methodology-renovation-budget-precedence"},"children":[{"type":"heading","level":4,"inline":[{"type":"text","value":"Renovation budget — which document the model reads"}]},{"type":"container","kind":"chain","attrs":{},"children":[{"type":"list","ordered":true,"attrs":{},"items":[{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Analyst override"}]},{"type":"text","value":" — A budget you set — including one you selected with \"Use this\" on CAPEX → Renovation budget sources — wins, with its justification note. An override equal to the selected document's figure keeps that document's badge."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"PIP / CapEx document — latest plan date"}]},{"type":"text","value":" — A separate PIP, owner budget, approved capital plan or estimate filed in the PIP / Renovation Budget lane (document type CAPEX, doc_subtype = pip — or left untagged, which the classifier decides) that states a PIP total (capex_plan.pip.total_usd). It is the more detailed source, so it outranks the OM. Among several, the newest plan date (capex_plan.document.plan_date, else the report date, else the upload date) wins — a newer approved capital plan supersedes an older brand PIP."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"OM broker pro forma"}]},{"type":"text","value":" — broker_proforma.renovation_budget_usd off the offering memorandum (badged \"OM Broker\") when no PIP / CapEx document states a budget."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Seed"}]},{"type":"text","value":" — The Fondok default, with a reason (no_document / no_source). No budget, whatever its source, displaces Year 1 — see Year-1 renovation displacement."}]}]}]},{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"Every candidate stays visible. CAPEX → Initial Renovation / PIP → "},{"type":"strong","children":[{"type":"text","value":"Renovation budget sources"}]},{"type":"text","value":" lists the OM figure and each PIP / CapEx document's figure with its page, plan date, status (brand-issued PIP · owner budget · approved capital plan · estimate) and preparer, marks the one the model is on, and says why each other one is not (superseded by a newer plan, outranked by a PIP, no PIP total extracted). The list is the worker's ("},{"type":"code","value":"GET /deals/{id}/renovation-budget-candidates"},{"type":"text","value":") and reports the same resolution the engines ran on; nothing is re-derived in the browser. A PIP whose stated total is more than 2% away from the sum of its own scope items is flagged for review at extraction — the value is never altered."}]},{"type":"paragraph","attrs":{"testid":"methodology-capex-lanes"},"inline":[{"type":"strong","children":[{"type":"text","value":"Three CapEx lanes, one of which feeds the model."}]},{"type":"text","value":" Every CapEx upload carries a lane ("},{"type":"code","value":"doc_subtype"},{"type":"text","value":"), set by the wizard slot it was dropped in or by the lane select in the Data Room: "},{"type":"strong","children":[{"type":"text","value":"PIP / Renovation Budget"}]},{"type":"text","value":" ("},{"type":"code","value":"pip"},{"type":"text","value":") is the day-one PIP, owner budget or approved capital plan and is the only lane the renovation budget reads; "},{"type":"strong","children":[{"type":"text","value":"Historic CapEx"}]},{"type":"text","value":" ("},{"type":"code","value":"historic"},{"type":"text","value":") is spend already incurred; "},{"type":"strong","children":[{"type":"text","value":"Future CapEx"}]},{"type":"text","value":" ("},{"type":"code","value":"future"},{"type":"text","value":") is a forward hold-period capital plan. A CapEx file with no lane (bulk drop, legacy upload) is classifier-assigned and may ground the model like a PIP — the Data Room files it under PIP / Renovation Budget so that is visible; re-lane it to take it out."}]},{"type":"paragraph","attrs":{"testid":"methodology-future-capex-reference-only"},"inline":[{"type":"strong","children":[{"type":"text","value":"Historic and Future CapEx are reference only."}]},{"type":"text","value":" A document filed under Historic CapEx or Future CapEx is listed separately as \"Reference only — not in the model\" — only its own namespace is read off it ("},{"type":"code","value":"historic_capex.*"},{"type":"text","value":" items and annual totals, or "},{"type":"code","value":"future_capex.*"},{"type":"text","value":" items by year) — and it is never incorporated into the renovation budget or any other engine input, even when the extractor also labelled rows in it "},{"type":"code","value":"capex_plan.pip.*"},{"type":"text","value":" or it prints a PIP total. The lane the analyst filed it under wins over the extractor's namespace. When such a document does state a PIP total, the list says so with the figure and a hint to re-tag it as PIP / Renovation Budget in the Data Room if it is in fact the day-one PIP."}]}]},{"type":"container","kind":"card","attrs":{},"children":[{"type":"heading","level":4,"inline":[{"type":"text","value":"Exit cap rate"}]},{"type":"container","kind":"chain","attrs":{},"children":[{"type":"list","ordered":true,"attrs":{},"items":[{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Analyst override"}]},{"type":"text","value":" — Inline-edited value wins."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"OM transaction-comps median"}]},{"type":"text","value":" — When the OM carries 3+ comparable sales with cap rates in the 3–15% sanity band, the median is the anchor."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Platform default 7.0% exit cap"}]},{"type":"text","value":" — Default when no comps are extracted."}]}]}]}]},{"type":"container","kind":"card","attrs":{},"children":[{"type":"heading","level":4,"inline":[{"type":"text","value":"Expense waterfall"}]},{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"Departmental, undistributed, and fixed-charge lines source from the T-12 first. Zero-valued extractor rows are treated as \"not present\" rather than authoritative — those gaps run on a ratio: an analyst override of that ratio first, else your portfolio P&L's ratio when one is on the deal, else the platform's hotel-type default. An uploaded P&L benchmark (CBRE Benchmarker / HotStats) is not one of those sources by itself. Its ratio only becomes an analyst override when you apply it (see the Benchmark column below)."}]},{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"When a P&L benchmark is uploaded (Comp Set / Market slot → \"P&L Benchmark (CBRE / HotStats)\"), its comp-set cost lines are mapped to the model's expense categories and shown on the Future P&L as a "},{"type":"strong","children":[{"type":"text","value":"Benchmark"}]},{"type":"text","value":" column beside the model's Year-1 ratios — departmental expense as a % of that department's revenue, every other line as a % of total revenue, plus the benchmark's POR and PAR. The ratio is computed from the report's own line and revenue totals where printed, else from its PAR figures, else taken as printed. Lines the report does not publish show \"—\". The benchmark is a suggestion: it changes the model only where the analyst applies it, as described under "},{"type":"em","children":[{"type":"text","value":"Benchmark column"}]},{"type":"text","value":" above."}]},{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"The waterfall produces "},{"type":"strong","children":[{"type":"text","value":"two"}]},{"type":"text","value":" distinct NOI figures, and every screen names which one it is showing:"}]},{"type":"list","ordered":false,"attrs":{},"items":[{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"NOI (before FF&E reserve)"}]},{"type":"text","value":" — GOP minus management fee (base, plus the incentive fee when one is modelled) minus fixed charges, "},{"type":"em","children":[{"type":"text","value":"excluding"}]},{"type":"text","value":" the FF&E reserve, matching the US cap-rate convention. Engine field "},{"type":"code","value":"expense.years[].noi_institutional"},{"type":"text","value":" (registry concept "},{"type":"code","value":"ebitda"},{"type":"text","value":"). This is the headline figure and the numerator of the entry cap rate. Where the product says simply \"NOI\", it means this."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Cash NOI (after FF&E reserve)"}]},{"type":"text","value":" — the same waterfall less the FF&E reserve, i.e. cash flow after reserves. Engine field "},{"type":"code","value":"expense.years[].noi"},{"type":"text","value":" (registry concept "},{"type":"code","value":"noi"},{"type":"text","value":"). The Debt engine divides by it for DSCR and debt yield, and the Returns engine capitalises it at the exit cap rate to derive the reversion — so the exit value is a Cash-NOI valuation, not a before-reserve one."}]}]},{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"The two differ by exactly the FF&E reserve. The reserve sits between them in the waterfall and contributes to Net Cash Flow. A pre-upgrade engine run that never persisted "},{"type":"code","value":"noi_institutional"},{"type":"text","value":" is labelled "},{"type":"em","children":[{"type":"text","value":"\"NOI (basis unconfirmed — pre-upgrade run)\""}]},{"type":"text","value":" rather than claiming a basis it cannot prove."}]}]},{"type":"container","kind":"card","attrs":{},"children":[{"type":"heading","level":4,"inline":[{"type":"text","value":"When a chain falls through to the seed"}]},{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"Every precedence chain above can end at the platform seed, and when it does the seed now carries a machine-readable reason rather than an unexplained default — one of the codes in Section 7: "},{"type":"code","value":"no_document"},{"type":"text","value":" when the deal carries no document of the type that would ground it, "},{"type":"code","value":"no_source"},{"type":"text","value":" when the document is there but none of its extracted fields resolves to that assumption, and "},{"type":"code","value":"str_unavailable"},{"type":"text","value":" when STR rates were requested but could not populate. Each grounded value carries the opposite record: the exact extraction row behind it — document, field path, page and the concept it resolved to — so \"which line of which statement is this?\" is answered from data, not inference. A figure derived from several rows (a growth CAGR, a corroborated median across statements) names its document and says so instead of pointing at a row that does not carry the number."}]}]}]},"sources":{"title":"Market-data assumptions","blocks":[{"type":"container","kind":"intro","attrs":{},"children":[{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"Every assumption surfaced on the Overview carries a provenance badge telling you exactly where the value came from. The legend below explains each source label and its precedence."}]}]},{"type":"container","kind":"card","attrs":{"testid":"market-tab-methodology"},"children":[{"type":"heading","level":4,"inline":[{"type":"text","value":"The Market Comps tab: comp set, the TTM comp-set blend, demand and supply growth"}]},{"type":"paragraph","attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"One comp set, one derivation."}]},{"type":"text","value":" The Market Comps tab's hotel count and its key count are computed from the same set: the "},{"type":"em","children":[{"type":"text","value":"active"}]},{"type":"text","value":" hotels of the STR roster ("},{"type":"code","value":"ttm_performance.compset.<n>.*"},{"type":"text","value":"). The roster is the "},{"type":"em","children":[{"type":"text","value":"union"}]},{"type":"text","value":" of every STR report on the deal — a hotel is matched across reports by its STR id ("},{"type":"code","value":"ttm_performance.compset.<n>.str_id"},{"type":"text","value":") or, failing that, by its name with STR's closed label stripped — because a closure often appears in only one report (a daily report lists “Closed - Blue Moon Hotel · 0 rooms” while the newer trend report still lists “Blue Moon Hotel · 75 rooms”). A hotel is treated as closed only when "},{"type":"em","children":[{"type":"text","value":"any"}]},{"type":"text","value":" report says so explicitly — an extracted "},{"type":"code","value":"status"},{"type":"text","value":" of "},{"type":"code","value":"closed"},{"type":"text","value":", or STR's own roster label, which prints a closed competitor as “Closed - <name>”. A zero-room row with neither marker stays an active hotel contributing no keys; nothing is inferred. Its keys are read from the newest report that lists a positive count. Closed hotels are listed on the roster with a “closed · excluded” chip and are excluded from "},{"type":"em","children":[{"type":"text","value":"both"}]},{"type":"text","value":" the count and the keys, and the roster note names the marker and the document that carried it — or says that none was found, in which case every listed hotel is counted. The report's own rollups ("},{"type":"code","value":"comp_set.comp_set_size"},{"type":"text","value":", "},{"type":"code","value":"comp_set.total_keys"},{"type":"text","value":") are kept for transparency but are never the headline while a roster exists; they are used only when no roster was extracted, and the tab says so. Which reports count as STR is decided by the lane each extraction ran in, not by the document's tag: a CoStar market report an analyst filed under “STR / Comp Set” is read as a market study (below) and never feeds the comp set or the blend. The same rule governs every other reader of STR data: the "},{"type":"code","value":"GET /deals/{id}/market-data"},{"type":"text","value":" envelope behind Index Analysis (a market report tagged STR lands in "},{"type":"code","value":"market_history"},{"type":"text","value":" as the market's actuals, never in "},{"type":"code","value":"str_trend"},{"type":"text","value":" as the subject's own history) and the STR forward forecast's subject TTM seed and monthly history, which read only extractions that ran in the STR lane. The envelope lists the roster of ONE report — the newest STR-lane extraction that carries one, never a merge of two reports by row position — and marks a hotel "},{"type":"code","value":"closed"},{"type":"text","value":" under the same rule as above (an explicit marker in any STR report on the deal); Index Analysis's comp-set keys sum only the hotels that are not closed. The STR forward forecast's comp-set RevPAR baseline likewise reads one report's roster, and its penetration indices come from the newest extraction. Each figure keeps the document and page it was read from."}]},{"type":"paragraph","attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"“TTM · comp-set blend” is defined on the card."}]},{"type":"text","value":" Market Occupancy, ADR and RevPAR are the comp set's blended trailing-twelve-month figures, recovered exactly from the STR penetration indices: comp-set Occupancy = subject TTM Occupancy ÷ MPI, comp-set ADR = subject TTM ADR ÷ ARI, comp-set RevPAR = subject TTM RevPAR ÷ RGI (each index is subject ÷ comp set, as STR publishes it). The Submarket Snapshot prints a methodology line composed from the inputs actually used: the STR report(s) the subject TTM and the indices were read from, the period (the subject's monthly series, e.g. Jul 2025 – Jun 2026, or the report year when no monthly series was extracted), and the active comp-set hotels with their keys and any closed hotel excluded. STR's comp-set figures are room-night totals across those hotels, so larger hotels weigh more; Fondok applies no weighting of its own, and a metric whose index is missing shows a dash rather than a substitute."}]},{"type":"paragraph","attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Demand Growth and Supply Growth read the market study."}]},{"type":"text","value":" A CoStar submarket report (document type "},{"type":"code","value":"MARKET_STUDY"},{"type":"text","value":", whichever upload lane it arrived through) feeds both tiles, and every figure names its document and field. Demand Growth is the report's demand (occupied room nights) growth: the trailing-twelve-month figure first ("},{"type":"code","value":"market_study.trend.ttm.demand_change_pct"},{"type":"text","value":"), then the latest actual year ("},{"type":"code","value":"market_study.trend.<YYYY>.demand_change_pct"},{"type":"text","value":"; the CBRE-style "},{"type":"code","value":"cbre_horizons.segment_all.<YYYY>.demand_change_pct"},{"type":"text","value":" rows inside the same document count too). When the report prints only the demand series, growth is derived as latest ÷ prior − 1 and both rows are named. Forecast-tagged years are never shown as history and are labelled as forecast when they are all the report has. Supply Growth is the pipeline over the existing inventory, with under construction and final planning kept separate: under-construction rooms ("},{"type":"code","value":"under_construction.total_rooms"},{"type":"text","value":", or the listed projects summed by their status) ÷ existing submarket rooms ("},{"type":"code","value":"market_study.supply.existing_rooms"},{"type":"text","value":", or the latest actual year of the supply series), and likewise final-planning rooms ÷ existing. The report's own supply change is shown alongside, never substituted. A tile the reports cannot populate shows a dash with "},{"type":"reason","code":"no_document"},{"type":"text","value":" when no market study is on the deal and "},{"type":"reason","code":"no_source"},{"type":"text","value":" (“not in the uploaded reports”) when the reports are there but the series is not — no growth rate is ever assumed."}]}]},{"type":"container","kind":"card","attrs":{},"children":[{"type":"container","kind":"badges","attrs":{},"children":[{"type":"container","kind":"badge","attrs":{"source":"t12_actual","name":"T-12 Actual"},"children":[{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"Year-1 anchor extracted from the deal's uploaded T-12. Out-years are grown forward at the configured expense / revenue growth rate."}]}]},{"type":"container","kind":"badge","attrs":{"source":"cbre_horizons","name":"CBRE Horizons"},"children":[{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"Forecast curve extracted from an uploaded CBRE Hotel Horizons report (subject submarket + chain-scale segment)."}]}]},{"type":"container","kind":"badge","attrs":{"source":"om_comps","name":"OM Comps"},"children":[{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"Median cap rate derived from the OM's \"Comparable Sales\" transaction-comps table."}]}]},{"type":"container","kind":"badge","attrs":{"source":"om_broker","name":"OM Broker"},"children":[{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"Broker proforma value extracted from the OM. Treat with appropriate skepticism — these are the broker's pitched numbers."}]}]},{"type":"container","kind":"badge","attrs":{"source":"pnl_benchmark","name":"P&L Benchmark"},"children":[{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"Industry benchmark margin from a CBRE / HotStats P&L benchmark report. Since 2026-10-15 the model no longer applies these by itself, so new runs do not carry this badge. An applied benchmark suggestion shows as "},{"type":"em","children":[{"type":"text","value":"Analyst override"}]},{"type":"text","value":" with its note. The badge can still appear on older runs and exports."}]}]},{"type":"container","kind":"badge","attrs":{"source":"analyst_override","name":"Analyst Override"},"children":[{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"Set via an inline editor, and carrying the analyst's own written justification. Wins over every other source — but only a value that actually changed is recorded as one; see \"What counts as an override\" and \"Every override carries a justification\" below."}]}]},{"type":"container","kind":"badge","attrs":{"source":"str_subject_ttm","name":"STR · Subject TTM Actual"},"children":[{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"The subject property's OWN trailing-twelve-month occupancy & ADR as reported by STR — an actual, not a forecast. This is what the model seeds the Base Year from when the STR basis is on: the forward forecast's Month-12 point can land far below the subject's current performance, which would understate the deal. Because the Base Year is a TTM window, Index Analysis shows N/A for the first forecast year's growth whenever the last historical column is a reported actual (a P&L fiscal year or an STR calendar year) — the two are not the same period basis."}]}]},{"type":"container","kind":"badge","attrs":{"source":"str_comp_set","name":"STR Comp-Set Rates"},"children":[{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"The comp set's blended occupancy & ADR shown on the Market Comps tab, applied as the Year-1 input by \"Use STR rates in the model\" (explicit overrides carrying the note \"STR comp-set market rates (Market tab)\"). This is the competitive set's performance, not the subject's own — the Market Comps tab states the comp-set benchmark and the model's Base Year as two separate figures and never claims the benchmark is the assumption."}]}]},{"type":"container","kind":"badge","attrs":{"source":"str_forecast","name":"STR Trend Forecast"},"children":[{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"The BASE STR forward-forecast scenario's Month-12 point — a projection of the subject, used only when the subject's own TTM is not extracted. P&L → Future P&L shows \"Active basis: Market / STR · Revert\" when the rates carry any of these three tags, and the Market Comps tab's STR card reads the same tags — \"STR / Market basis active\", \"STR rates unavailable — using T-12 base\", or \"Pending re-run\" when the worker has not tagged the rates yet — never the request flag alone."}]}]},{"type":"container","kind":"badge","attrs":{"source":"str_forecast_unavailable","name":"STR Unavailable"},"children":[{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"STR rates were requested but could not populate (no STR Trend extraction, coverage too low, or a loader failure). The model stays on the T-12 base and says so — the STR seed is never silently \"active\". Reason code: "},{"type":"reason","code":"str_unavailable"},{"type":"text","value":"."}]}]},{"type":"container","kind":"badge","attrs":{"source":"derived_from_revpar_growth","name":"Derived from RevPAR Growth"},"children":[{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"An analyst RevPAR-growth override derives ADR growth — (1 + RevPAR growth) ÷ (1 + occupancy growth) − 1 — with the occupancy path held, so the lever moves operating NOI. Setting ADR growth explicitly takes direct control."}]}]},{"type":"container","kind":"badge","attrs":{"source":"str_segmentation","name":"STR Segmentation"},"children":[{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"A demand-segment figure the deal's STR Segmentation report states: a segment's share of room nights, the transient channel split when the report's channel-mix block carries it, or a segment ADR."}]}]},{"type":"container","kind":"badge","attrs":{"source":"platform_default_segmentation","name":"Platform default — no segmentation data on file"},"children":[{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"A segment-model figure the STR Segmentation report does not state, filled by a platform default: every channel cost (BAR 2%, OTA 20%, corporate 8%, group 5%, contract 2%), the 60/30/10 BAR / OTA / corporate split of transient demand when the report has no channel-mix block, and a segment ADR at its ratio to the property ADR (corporate 90%, group 92%, contract 65%). A suggestion, never labelled as STR data; the Revenue Mix sheet and the memo name these figures under the table. Runs saved before 30 October 2026 carry the older “Segment default” badge on every segment figure."}]}]},{"type":"container","kind":"badge","attrs":{"source":"platform_default_renovation_split","name":"Platform default split"},"children":[{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"The renovation budget's breakdown into hard costs, soft costs and professional fees at the platform default 75% / 15% / 10% — no itemized renovation budget is on file."}]}]},{"type":"container","kind":"badge","attrs":{"source":"index_assumption","name":"Index Analysis Assumption"},"children":[{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"Index Analysis indexes the subject against one of three benchmarks, chosen on Market Comps → Index Analysis: the "},{"type":"strong","children":[{"type":"text","value":"STR competitive set"}]},{"type":"text","value":" (the default — subject STR TTM ÷ the published MPI / ARI, the same blend Market Overview shows), a "},{"type":"strong","children":[{"type":"text","value":"market / chain-scale benchmark"}]},{"type":"text","value":" (the market-wide or chain-scale segment occupancy & ADR in the deal's CoStar / STR market reports), or a "},{"type":"strong","children":[{"type":"text","value":"CoStar Property Analytics comp set"}]},{"type":"text","value":" (only when that export has been extracted — otherwise the option is disabled and says why). Each benchmark figure names its document and page. Four assumptions ride on the choice — market occupancy growth, market ADR growth, and the MPI / ARI penetration targets — each showing its document source, the documents a computed default used, or \"Your override\". They feed the Future P&L only while \"Use STR rates in the model\" is on and the STR seed has landed: then Year-1 occupancy = benchmark occupancy × MPI target, Year-1 ADR = benchmark ADR × ARI target, and the growth rates replace the model's, each only where you set one and never over an explicit override of that input. With the toggle off nothing moves. Index Analysis also restates the Future P&L Base Year (revenue engine Year 1, its source and every step to it) beside its own figures, and the STR subject TTM it indexes against is named as a different source and period. "},{"type":"br"},{"type":"strong","children":[{"type":"text","value":"Targets by year."}]},{"type":"text","value":" The penetration targets can be set per model year ("},{"type":"code","value":"index_mpi_target_by_year"},{"type":"text","value":" / "},{"type":"code","value":"index_ari_target_by_year"},{"type":"text","value":"; a by-year entry beats the all-years target). The all-years target drives "},{"type":"strong","children":[{"type":"text","value":"Year 1 only"}]},{"type":"text","value":": Years 2+ are indexed only where a by-year target is set for that year or the analyst overrides that metric's market growth; otherwise the year follows the model's own growth and is flagged "},{"type":"code","value":"scalar_year1_only"},{"type":"text","value":", so an existing deal never changes because a report's default growth appeared. With the STR basis on, each indexed model year's occupancy = that year's benchmark occupancy × MPI target ÷ 100 and ADR = that year's benchmark ADR × ARI target ÷ 100, where the benchmark series follows the selected method: the STR or CoStar comp set is the reported TTM level in Year 1 grown at the market occupancy / ADR growth assumptions after it; the market benchmark is the reported level in Year 1 and the CBRE Horizons forecast for that model year's calendar year after it (the segment table named like the chosen segment when the report carries one, else All Hotels). RGI is derived — MPI × ARI ÷ 100 — never an input. A year with a target but no benchmark value (no growth assumption, no CBRE year, no close date to place it) is flagged"},{"type":"code","value":" benchmark_unavailable"},{"type":"text","value":": the model keeps its own growth from the last driven year and no figure is invented. Every driven year records the benchmark (value, document, page or growth step), the target and the resulting occupancy / ADR on the revenue output ("},{"type":"code","value":"revenue.index_drivers_by_year"},{"type":"text","value":") and in the lineage of that year's rooms revenue; the Future P&L Assumptions sheet carries one row per metric per year ("},{"type":"code","value":"index_mpi_target_by_year.3"},{"type":"text","value":") so the targets round-trip through Excel with the same justification rule. "},{"type":"br"},{"type":"strong","children":[{"type":"text","value":"Target units."}]},{"type":"text","value":" A target is index points 25–250 (100 = parity with the benchmark) or a ratio 0.25–2.5 (1.0 = parity) — the two bands do not overlap, so a value names its own unit: 1.10 is 110 points everywhere (the panel, the by-year grid, the penetration table, the at-target opportunity and the model), never 1.1. The range is checked on every write "},{"type":"em","children":[{"type":"text","value":"and every read"}]},{"type":"text","value":": a legacy stored target outside both bands (e.g. 5, written before the check existed) is ignored by the model and the grid — it never moves Year-1 occupancy or ADR — and the panel shows \"—\" sourced \"Stored override ignored\" (never \"Your override\") with \"Stored all-years MPI target 5 is outside 25–250 index points … re-enter it\"; a by-year entry out of range falls back to the all-years target and is named the same way."}]}]},{"type":"container","kind":"badge","attrs":{"source":"index_assumption","name":"Index Analysis · Columns & Rows"},"children":[{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"The Index Analysis year columns follow the acquisition close calendar — the same"},{"type":"code","value":"projection_calendar_years"},{"type":"text","value":" the Future P&L prints: Year 1 is the calendar year of the first operating month after close and sits in the first forecast column, the forecast columns are exactly the model horizon (nothing is carried forward beyond it — no held-flat occupancy or 3% ADR extension), and the six columns before Year 1 are history. With no close date the forecast columns read \"Year N\" with a one-line note; a year is never guessed. Subject history is the STR Trend annual subject figures ("},{"type":"code","value":"ttm_performance.subject.annual.<YYYY>"},{"type":"text","value":") where the report carries them, else the P&L fiscal year — a Source row says which per column. The comp-set table (titled "},{"type":"strong","children":[{"type":"text","value":"STR Competitive Set"}]},{"type":"text","value":" — it is STR data, never labelled a CoStar market table) is the STR TTM blend (subject ÷ MPI / ARI / RGI) in the last historical column. Its forecast columns are the same series the STR comp-set index method runs on: the TTM level as the Year-1 benchmark, grown at the market occupancy / ADR growth assumption after it (the document default or your override), banded \"comp set grown at market growth (assumption)\" with the growth source on hover. STR publishes no comp-set forecast, so this is an assumption, never an STR figure; with no growth value the out-years stay \"—\" with the reason, and the subject's growth is never re-scaled into them. The by-year fair share, variances and Revenue Opportunity at Par fill from it. A separate Market row carries market-level actuals (market study / STR market rows) by calendar year and, as its forecast, CBRE Horizons placed by the report's own calendar year ("},{"type":"code","value":"cbre_horizons.year_<n>.calendar_year"},{"type":"text","value":", pipeline v7) and labelled Market / CBRE Horizons with document and page — a CBRE forecast is a market forecast, not a comp-set forecast. A calendar shorter than the horizon is not extended: a model year the engine did not place reads \"Year N\" with no calendar year. "},{"type":"strong","children":[{"type":"text","value":"Actual vs forecast labels."}]},{"type":"text","value":" Year 1 uses the reported TTM and Year 2 onward the CBRE Horizons forecast (market benchmark), so every benchmark value names its kind, source and period with a worded chip — never colour alone — and a one-line label: "},{"type":"strong","children":[{"type":"text","value":"Actual"}]},{"type":"text","value":" \"Actual · STR TTM May 2025 · <document>\" (the STR TTM window's period end — the last month of the subject's monthly series, else the report period the STR reader resolved — served as "},{"type":"code","value":"subject_period_end"},{"type":"text","value":" on"},{"type":"code","value":"GET /market/{id}/index-methodology"},{"type":"text","value":" and "},{"type":"code","value":"str_trend.ttm_period_end"},{"type":"text","value":" on"},{"type":"code","value":"GET /deals/{id}/market-data"},{"type":"text","value":"); "},{"type":"strong","children":[{"type":"text","value":"Forecast"}]},{"type":"text","value":" \"Forecast · CBRE Horizons 2027 · <document> p.N\" (with the report's publication date, "},{"type":"code","value":"cbre_report_date"},{"type":"text","value":", on hover); and "},{"type":"strong","children":[{"type":"text","value":"Assumption"}]},{"type":"text","value":" \"Assumption · grown at market growth\" for the comp-set series past Year 1. Market-study and STR annual history, and P&L fiscal years, are labelled Actual with their year and document. The by-year grid prints the chip and label under each benchmark value plus one line naming the Year-1 actual and the Year-2+ forecast; the Index Analysis tables carry the chip in their Source row and the full label in a Basis row. A value with no source shows \"—\" and no chip. The labels are display only — the revenue engine's by-year drivers are unchanged. Penetration rows follow the benchmark selected on Index methodology. With the STR comp set: the STR-published MPI / ARI / RGI in the TTM anchor column; across the forecast columns the analyst's MPI / ARI target for that model year where one is set (by-year, else the all-years target; RGI derived as MPI × ARI ÷ 100) while \"Use STR rates in the model\" is on — so the index rows only print a target the Subject rows actually run on — else the published index held flat, with a one-line note when targets are set but not applied; the hover text says which. With the market benchmark (or the CoStar comp set) selected, the index rows read \"vs <benchmark>\": the anchor column is the subject STR TTM ÷ that benchmark × 100 and each forecast column is the subject ÷ that year's benchmark (the same by-year benchmark the model indexes against), or the analyst's target where one applies — never the STR-published indices, which are against the comp set; the subject ÷ market indices, occupancy (pts), ADR ($ and %) and RevPAR variances to the comp set, Fair Share of Supply = subject rooms ÷ (comp-set rooms + subject rooms), fair-share occupancy, actual share of demand, fair-share rooms revenue, and the signed Revenue Opportunity at Par and at Target, the latter computed per year against the analyst-set target that applies to that year and priced on the selected benchmark (target RevPAR = benchmark occupancy × MPI ÷ 100 × benchmark ADR × ARI ÷ 100). It is gated exactly like the index rows: only while \"Use STR rates in the model\" is on, otherwise \"—\" with \"Targets set but not applied\". A document default — the published index itself — is not a target, so with none set the row is \"—\" and says so. Every cell shows its formula and inputs on hover; a cell with no reported input is \"—\"."}]}]},{"type":"container","kind":"badge","attrs":{"source":"seed","name":"Seed Default"},"children":[{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"Platform default. Surfaced as a Seed badge with grey tone — no deal-specific data has overridden this yet. The senior origination fee (1.50% of the senior loan) is one of these: a Fondok seed, not a document-sourced figure, editable on Financing and the single source for the Sources & Uses “Senior Loan Origination Fee” line and Overview “Financing Costs”."}]}]},{"type":"container","kind":"badge","attrs":{"source":"deal_row","name":"Deal Row"},"children":[{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"Sourced from the deals table (entered on the create-deal wizard or PATCHed via the API). Project name, city, brand, keys, service (the FON-115 property type — OM-only, fill-only, never guessed; see services/property_type.py), the reopening / re-flag date — and the "},{"type":"strong","children":[{"type":"text","value":"purchase price"}]},{"type":"text","value":": the wizard's \"Purchase / Indicative Price\" field is parsed to whole dollars (\"$36.4M\", \"36,400,000\"; a range such as \"$120-140M\" stores its "},{"type":"em","children":[{"type":"text","value":"midpoint"}]},{"type":"text","value":" and is labelled \"range midpoint\" on the Review step) and saved as "},{"type":"code","value":"purchase_price"},{"type":"text","value":", which seeds the model's purchase price with this badge rather than \"Seed\". A bare figure under $1,000,000 with no unit (\"36400\", \"1,200\") and a two-year period (\"2024-2025\") are not read as prices — the hint asks for M / MM or the full dollars. Text that does not read as a price is kept as a note and sends nothing — the model keeps its seed until the analyst sets the price on CAPEX → Deal Summary, where it stays editable. The Property Name is not a deal-row field — see below."}]}]}]}]},{"type":"container","kind":"card","attrs":{},"children":[{"type":"heading","level":4,"inline":[{"type":"text","value":"What counts as an override"}]},{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"Opening a field to inspect it never changes its lineage. An override is recorded only when the saved value "},{"type":"strong","children":[{"type":"text","value":"differs from the current effective value"}]},{"type":"text","value":" after normalisation — the draft you type and the value the engine stores are compared in the field's own unit, so \"6.80\" typed over a stored 0.068, \"65\" over 0.65, and \"$23,660,000\" over 23660000 are all the same number and write nothing. Every editor exits without writing on "},{"type":"strong","children":[{"type":"text","value":"Cancel, Esc or a click outside"}]},{"type":"text","value":", and a Save that changed nothing says so (\"No change — provenance unchanged\") instead of persisting a duplicate."}]},{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"The same rule holds server-side, for overrides already stored: a value equal to what the deal resolves to on its own is reported under "},{"type":"strong","children":[{"type":"text","value":"its source's badge"}]},{"type":"text","value":" (T-12, OM, benchmark or seed), not as an analyst override. The stored override is left exactly as the analyst wrote it and the engines still read it, so no number moves — only the claim about where the number came from. Use "},{"type":"strong","children":[{"type":"text","value":"Clear override"}]},{"type":"text","value":" in the provenance popover to remove one."}]}]},{"type":"container","kind":"card","attrs":{},"children":[{"type":"heading","level":4,"inline":[{"type":"text","value":"Every override carries a justification"}]},{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"An override that "},{"type":"strong","children":[{"type":"text","value":"changes a number"}]},{"type":"text","value":" carries an analyst justification. It is required at the moment of the edit, stored with the value in the deal's "},{"type":"code","value":"field_overrides"},{"type":"text","value":" as "},{"type":"code","value":"{ value, note }"},{"type":"text","value":", and shown to reviewers in the provenance popover next to the number and on the override's row in the activity trail. The rule is enforced in the API as well as in the editor: a save that changes an engine input without a note is rejected ("},{"type":"code","value":"422 override_note_required"},{"type":"text","value":"), so there is no path — UI, script or integration — that can record an unexplained number."}]},{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"The justification is never written for you. Fondok stores what the analyst typed or nothing at all; it never fills the field with a generated sentence about which page the edit was made on."}]},{"type":"paragraph","attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"What is exempt, and why."}]},{"type":"text","value":" The requirement follows one rule — a note is needed when the key routes into engine input. Edits that change no modelled number need none: the Historical P&L worksheet's row layout ("},{"type":"code","value":"worksheet_layout"},{"type":"text","value":", presentation only), the "},{"type":"strong","children":[{"type":"text","value":"Stabilization Year"}]},{"type":"text","value":" (it selects which projection year the stabilized figures are read from and moves no return), the "},{"type":"strong","children":[{"type":"text","value":"Property Name"}]},{"type":"text","value":" (a name, not a number), the Completion Guarantee covenant status (qualitative — no covenant math), the number of promote tiers in the waterfall (its shape, not a value in it), and the IC memo's prose. Clearing an override is a revert to source, not an override, and needs no note either."}]},{"type":"paragraph","attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Target LIRR (levered IRR), Target MOIC and Target Stabilized Yield on Cost are not overrides."}]},{"type":"text","value":" They are stored on the deal as stated objectives — the benchmark the returns are read against and the hurdle the Max Price Solver prices to — not replacements for a value Fondok sourced from a document. They are editable without a justification, and a value that came from a source is never behind them. Target Stabilized Yield on Cost is kept in the deal's "},{"type":"code","value":"field_overrides"},{"type":"text","value":" as "},{"type":"code","value":"target_stabilized_yoc"},{"type":"text","value":" and is exempt from the note rule on both the browser and the API for the same reason."}]}]},{"type":"container","kind":"card","attrs":{},"children":[{"type":"heading","level":4,"inline":[{"type":"text","value":"Project Name vs Property Name"}]},{"type":"paragraph","attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Project Name"}]},{"type":"text","value":" is the analyst's confidential deal identifier (e.g. \"Project Unicorn\") — a deal-row field you set and rename on the Overview; document extraction never writes it. "},{"type":"strong","children":[{"type":"text","value":"Property Name"}]},{"type":"text","value":" is the asset as named in the offering documents (OM first, then the STR subject name) and is never inferred from the Project Name — it shows \"—\" until the OM is extracted ("},{"type":"reason","code":"no_document"},{"type":"text","value":"). The two are stored independently and editing one never changes the other. An analyst may override the Property Name from its Overview row: the override is stored as "},{"type":"code","value":"field_overrides[\"property_overview.name\"]"},{"type":"text","value":", the extracted value and its source page are preserved, and \"Restore sourced value\" drops the override so the extracted name comes back."}]}]},{"type":"container","kind":"card","attrs":{},"children":[{"type":"heading","level":4,"inline":[{"type":"text","value":"Which documents set the deal's key count, brand and city"}]},{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"Only documents about the subject property — the Offering Memorandum, a T-12, P&Ls, a Hotel Program document or an Other Property Info sheet — can set the deal's key count, and when more than one of them states a room count the Offering Memorandum wins. The deal carries two brands: the existing brand comes from the Offering Memorandum and is filled only while it is empty, and the proposed brand is the analyst's own choice and is never touched by a document. Market reports, STR reports, comparable sets, CapEx budgets, insurance documents and leases describe other things, so they never change the key count, brand or city. The city is filled only while it is empty, and never from a street address. Until a qualifying document has been extracted the deal header shows \"—\" for keys rather than a count of zero."}]},{"type":"paragraph","attrs":{"testid":"brand-positioning-methodology"},"inline":[{"type":"strong","children":[{"type":"text","value":"Brand and positioning."}]},{"type":"text","value":" Positioning is a deal setting, chosen on the wizard's Brand and Positioning step and editable on the Overview's Investment Profile card. Choosing a brand "},{"type":"em","children":[{"type":"text","value":"suggests"}]},{"type":"text","value":" that brand's "},{"type":"strong","children":[{"type":"text","value":"STR chain scale"}]},{"type":"text","value":" (STR's published chain-scale table, February 2026) wherever STR lists the brand; a brand STR does not cover suggests Fondok's own classification, and a brand with no single scale (Independent / Unflagged, a multi-scale collection) suggests nothing. A suggestion is only that: in the wizard the suggested tier card is marked \"Suggested from brand\" and the tier changes only when you select a card; on the Overview, while the deal has no tier (\"Default\"), the current flag's scale is offered beside the Positioning select with a one-click "},{"type":"em","children":[{"type":"text","value":"Use"}]},{"type":"text","value":", and changing the flag writes only the brand. A deal created without selecting a tier therefore has none (\"Default\") until you choose one or the Offering Memorandum suggests one (below). This is what keeps the recorded source honest — \"Analyst\" means a tier you actually chose — and leaves the OM able to suggest; a tier the wizard filled from the brand would have been recorded as yours and would have blocked the OM for good. Deals created before 17 October 2026 may carry a tier the wizard filled from the brand; it is stored and labelled as the analyst's. The analyst can set a different tier for this property at any time, and the stored value is what the model reads: it is the subject's chain scale for the comparable-sales match and for which portfolio P&L library entries may contribute ratios. \"Default\" means no tier was chosen. Then no chain-scale filter is applied to the portfolio P&L library, and the comparable-sales match uses an approximate scale from the deal's service type (Luxury → Luxury; Full Service or Resort → Upper Upscale; Select Service → Upper Midscale; Limited Service → Midscale), or no chain-scale match at all when the service type is blank. "},{"type":"strong","children":[{"type":"text","value":"Positioning from the Offering Memorandum's brand."}]},{"type":"text","value":" When an Offering Memorandum is extracted and the deal has no tier (\"Default\" or blank), the brand the OM names is looked up in the same brand catalog the wizard uses. Only a confident match counts: the brand's full name, one of its listed aliases, or its short form (\"Kimpton\" for Kimpton Hotels & Restaurants, \"Hampton\" for Hampton by Hilton), compared without regard to case, accents or punctuation; or a brand string that starts with one of those followed only by a property name (\"Kimpton Angler's\"). There is no similarity guessing: a name shared by several brands (\"Starwood\"), a string that also names a second brand (\"Marriott Courtyard\"), or a brand that is not in the catalog suggests nothing. When the matched brand has an STR chain scale, that scale becomes the deal's positioning; a brand STR does not publish a single scale for (Independent / Unflagged, multi-scale collections, brands with no STR row) suggests nothing, and Fondok's own classification is not used here. The Overview shows where the tier came from beside the Positioning select — \"From OM brand Kimpton → STR Upper Upscale (document, page)\", or \"Analyst\" for a tier chosen in the wizard or on the Overview — and the page reads \"page not cited\" when the extraction did not record one. A third chip, \"Source not recorded\", marks a tier stored before Fondok began recording where positioning came from (the source columns were added without rewriting history, so no provenance is asserted that was never recorded); choosing a tier on the Overview records that choice as the analyst's. A tier the analyst chose, or one already stored, is never replaced by an OM; a later OM never replaces an OM-filled tier either; choosing another tier overrides it and is recorded as the analyst's; setting it back to \"Default\" clears the source, so the next OM may suggest again. Only the OM suggests positioning — T-12s, P&Ls, market studies and STR reports never do. The suggestion is applied when the OM is extracted and takes effect on the next model run; deals extracted earlier keep their stored positioning."}]},{"type":"paragraph","attrs":{"testid":"market-submarket-methodology"},"inline":[{"type":"strong","children":[{"type":"text","value":"City, market and submarket."}]},{"type":"text","value":" These are three separate deal fields. "},{"type":"strong","children":[{"type":"text","value":"City"}]},{"type":"text","value":" is the property's city (optional; filled from the Offering Memorandum only while empty, as above). "},{"type":"strong","children":[{"type":"text","value":"Market"}]},{"type":"text","value":" and "},{"type":"strong","children":[{"type":"text","value":"Submarket"}]},{"type":"text","value":" are chosen on the wizard's first step, shown — and correctable at any time — on the Overview's Investment Profile card; no engine reads them today, so changing them never re-runs the model. "},{"type":"strong","children":[{"type":"text","value":"The taxonomy list:"}]},{"type":"text","value":" the CoStar geography export (markets and submarkets, no vendor ids), loaded by "},{"type":"code","value":"scripts/load_str_markets.py --format costar-geography --version <v>"},{"type":"text","value":" (dry run by default; "},{"type":"code","value":"--commit"},{"type":"text","value":" is refused on any validation problem; "},{"type":"code","value":"--report-orphans"},{"type":"text","value":" lists deals whose stored key left the list). Fondok mints deterministic taxonomy keys from the names — "},{"type":"code","value":"costar:<slug of market>"},{"type":"text","value":" for a market, "},{"type":"code","value":"<market key>/<slug of submarket>"},{"type":"text","value":" for a submarket — because submarket names repeat across markets (the key is (Market, Submarket)); the loader refuses a file in which two distinct names collide on one key. The deal stores the keys in "},{"type":"code","value":"str_market_id"},{"type":"text","value":" and "},{"type":"code","value":"submarket_id"},{"type":"text","value":" (the first column name predates the CoStar list and was kept rather than renamed — a rename is a wider migration; it holds a Fondok key, not a vendor id; decision of 30 October 2026, FON-96) and the keys are hidden everywhere — the UI says “CoStar market” / “CoStar submarket of <market>”. Each market is "},{"type":"code","value":"metro"},{"type":"text","value":" (named “City - ST USA”) or "},{"type":"code","value":"regional"},{"type":"text","value":" (named in words), recorded in "},{"type":"code","value":"str_markets.market_type"},{"type":"text","value":"; "},{"type":"code","value":"reference_datasets"},{"type":"text","value":" records the loaded version, SHA-256, row counts and the licence flag, and "},{"type":"code","value":"/admin/health"},{"type":"text","value":" reports them in its "},{"type":"code","value":"reference"},{"type":"text","value":" block. "},{"type":"strong","children":[{"type":"text","value":"Selection:"}]},{"type":"text","value":" a typed market or submarket takes a key only when it matches exactly one entry (case- and punctuation-insensitive, “Chicago, IL” ≡ “Chicago - IL USA”); the worker refuses a key that is not in the loaded list, and a submarket key that is not under the market key ("},{"type":"code","value":"submarket_not_in_market"},{"type":"text","value":"); a market change without a submarket key clears the submarket key. Typed values are stored with null keys as analyst-entered ("},{"type":"code","value":"market_source = analyst"},{"type":"text","value":"). "},{"type":"strong","children":[{"type":"text","value":"Licensing:"}]},{"type":"text","value":" the list is served to an internal workspace always, and to an external workspace only when both the loaded dataset's licence flag ("},{"type":"code","value":"--licensed-external"},{"type":"text","value":" at load time) and the "},{"type":"code","value":"MARKET_TAXONOMY_SERVE_EXTERNAL"},{"type":"text","value":" setting are on; otherwise that workspace sees the public 62-name STR market list and no submarket suggestions, and the worker refuses a new key from it ("},{"type":"code","value":"market_list_unavailable"},{"type":"text","value":") without saying whether the key exists. "},{"type":"strong","children":[{"type":"text","value":"Fill from the OM:"}]},{"type":"text","value":" after the metadata sync, a deal with no market may receive one only when an OM location phrase, normalised, equals exactly one metro market name — never a regional market, never two candidates — and a submarket only within that market on the same exact rule; recorded as "},{"type":"code","value":"market_source = om_exact_match"},{"type":"text","value":" (mirrors "},{"type":"code","value":"positioning_source"},{"type":"text","value":") with the document, page and phrase, and audited as "},{"type":"code","value":"deal.market_matched_from_extraction"},{"type":"text","value":"; a workspace the list is withheld from is never filled. An analyst's value is never overwritten. Fondok never invents a market, a submarket or a key, and the key is never shown as a vendor identifier."}]}]},{"type":"container","kind":"card","attrs":{},"children":[{"type":"heading","level":4,"inline":[{"type":"text","value":"Which statement is the Year-1 basis"}]},{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"Year-1 occupancy, ADR, revenue lines and expense lines all come from one statement: the document the Data Room badges as "},{"type":"strong","children":[{"type":"text","value":"Primary source"}]},{"type":"text","value":". The engines and the badge now share one ranking — full-year statements before partial ones, the most recent period first, and a T-12 ahead of a calendar-year P&L of the same year. A T-12 whose extraction carries no period label is still treated as a trailing-twelve, and when it carries no date at all it is taken as the current period, because an analyst uploads a T-12 as the latest statement. Older annual P&Ls never blend into Year-1: a line is only corroborated across statements that describe the same period (two uploads of the same T-12, or a summary and a detailed P&L of one year), so every Year-1 number traces to a single row of the primary statement. The earlier years still feed the Historical P&L grid and the variance checks."}]}]},{"type":"container","kind":"card","attrs":{},"children":[{"type":"heading","level":4,"inline":[{"type":"text","value":"Hover any number to trace it"}]},{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"Provenance runs on two levels, and every figure on the platform carries one or the other:"}]},{"type":"list","ordered":false,"attrs":{},"items":[{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Inputs — “where did this come from?”"}]},{"type":"text","value":" Assumptions (occupancy, ADR, growth rates, LTV, rate, exit cap) show a source badge / dotted underline colored by origin: green when grounded in the deal's own docs (T-12, OM, CBRE), amber when it's still a seed/benchmark default, violet when an analyst overrode it. When it's backed by a document the badge is clickable — a "},{"type":"icon","name":"Link2"},{"type":"text","value":" jumps you to that source in the Data Room."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Outputs — “how was this computed?”"}]},{"type":"text","value":" Modeled values (rooms & total revenue, NOI, GOP, debt service, DSCR, equity multiple, gross sale, IRR) hover to show the exact formula plus every named input, and each input chains one hop further — back to a source document, a seed/benchmark, an analyst override, or another computed value. Follow any number to ground."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"NOI pin (reconciliation override)."}]},{"type":"text","value":" A deal can carry "},{"type":"code","value":"noi_override_by_year"},{"type":"text","value":" — an analyst-entered per-year NOI schedule (an analyst-entered schedule used to reconcile to a source model) — and optionally "},{"type":"code","value":"terminal_noi_override"},{"type":"text","value":" for the exit-year reversion NOI. While either is set, the Debt and Returns engines read that schedule instead of the operating model, so RevPAR-growth / expense edits do not move NOI. P&L → Future P&L shows an \"NOI pinned to an analyst schedule\" notice whenever the pin is present (and says when terminal NOI is also pinned) — the operating model's own figure is withheld under "},{"type":"reason","code":"pin_active"},{"type":"text","value":"; "},{"type":"strong","children":[{"type":"text","value":"Clear pin"}]},{"type":"text","value":" deletes the override(s) from "},{"type":"code","value":"field_overrides"},{"type":"text","value":" and re-runs the model, after which NOI follows the operating assumptions again."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"IRR is calculated, and says so."}]},{"type":"text","value":" IRR has no closed form — it's the discount rate that sets the NPV of the equity cash flows to zero, solved iteratively (Newton's method, bisection fallback). Its hover states that explicitly and lists the year-by-year cash-flow stream the solver ran over."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Total Revenue is the statement's own line."}]},{"type":"text","value":" In P&L → Historical P&L the Total Revenue row shows the statement's own stated total when it publishes one ("},{"type":"code","value":"p_and_l_usali.total_revenue_usd"},{"type":"text","value":"), as an extracted cell whose SOURCE panel names that field, page and confidence. Only when the statement states no total is the row the sum of the extracted revenue lines (Rooms + F&B + Other), and then it carries a "},{"type":"em","children":[{"type":"text","value":"calculated"}]},{"type":"text","value":" label. The two can disagree — a statement may state $13.48M while the lines it itemises sum to $12.3M — and the "},{"type":"strong","children":[{"type":"text","value":"Revenue footing"}]},{"type":"text","value":" row under the grid always compares the sum of the lines against the stated total and shows the difference; the cell is never footed against itself, and no total is invented when neither exists. A stated total adds no \"to review\" count of its own: it is reviewed through the lines that foot to it. Correcting a revenue line at source re-sums a derived total; a stated total stays what the statement says, and the footing check carries the resulting difference."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Every historical column states its period."}]},{"type":"text","value":" A statement is read on one of three bases and the column says which: a "},{"type":"strong","children":[{"type":"text","value":"full year"}]},{"type":"text","value":" (\"FY2024\"), "},{"type":"strong","children":[{"type":"text","value":"year-to-date"}]},{"type":"text","value":" through a month end (\"YTD Mar 2025\"), or a "},{"type":"strong","children":[{"type":"text","value":"trailing twelve months"}]},{"type":"text","value":" ending at a month end (\"T12 Mar 2025\"). The basis comes from the statement's own "},{"type":"code","value":"period_type"},{"type":"text","value":", and failing that from its classified document type — the same resolution the engines use, so the column header and the number cannot disagree. The Period control on P&L → Historical P&L filters the columns by that basis, and the SOURCE panel names the period alongside the document (\"T-12 ending Mar 31, 2025\") so a \"2025\" column is never ambiguous between a year-to-date and a trailing twelve. When the basis cannot be established — no stated period type, and a classification that would have to be guessed at — the column renders the "},{"type":"strong","children":[{"type":"text","value":"bare year with a \"basis unknown\" chip"}]},{"type":"text","value":" under "},{"type":"reason","code":"period_mismatch"},{"type":"text","value":", never an invented FY or T-12. A period-end date that falls outside the column's own year is likewise dropped rather than shown."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Primary financial source."}]},{"type":"text","value":" When several statements cover the same periods, Fondok ranks them — full-year sources over partial (monthly / YTD), most-recent period, then most-detailed — and badges the winner “Primary source” in the Data Room so it's clear which statement drives the historicals."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Cross-checked across statements."}]},{"type":"text","value":" When more than one full-year statement is uploaded, Fondok doesn't just trust the top-ranked one — it cross-checks each revenue and expense line across all of them and grounds Year-1 on the corroborated (median) value. So if a single statement mis-reads one line — say F&B revenue comes through an order of magnitude low — the other full-year statements outvote it and the model isn't skewed by one bad extraction. A line reported by only one statement is used as-is."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"One review state, Data Room ↔ P&L."}]},{"type":"text","value":" An extracted historical value is \"to review\" when its extraction confidence is below 85% and it hasn't been accepted or corrected — and only if it has a cell in P&L → Historical P&L (a value with nowhere to land is never counted). The Data Room's per-statement \"N to review\" badge is exactly the number of red cells in that statement's column; the global count is their sum. Every red cell is pinned to its own column's statement, so its SOURCE panel names — and its Accept / Edit acts on — that document, never another year's. Clicking a badge opens the Historical P&L with that statement's column pinned and the first flagged cell in view; accepting or correcting a value clears the cell and both counts at once. Two statements that resolve to the same period keep separate columns (\"2023\", \"2023 (2)\") and the coverage strip says so."}]}]}]},{"type":"container","kind":"card","attrs":{},"children":[{"type":"heading","level":4,"inline":[{"type":"text","value":"As-of rule"}]},{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"An underwriting is a claim about what was knowable on a date. When a deal sets an underwriting as-of date, Fondok will not ground a market assumption on a report published after it: a CBRE Horizons forecast, an OM comparable-sales table or an STR report dated later is refused, the assumption keeps the basis it already had, and the badge says "},{"type":"em","children":[{"type":"text","value":"unavailable"}]},{"type":"text","value":" with the reason "},{"type":"reason","code":"not_knowable_as_of"},{"type":"text","value":" — never a silent substitution. The comparison respects how precisely the report is dated: a document known only to a year is compared year-to-year, a quarter quarter-to-quarter, so a report from the underwriting year is admitted rather than refused on a 31-December stamp. A report whose date cannot be established is "},{"type":"em","children":[{"type":"text","value":"used"}]},{"type":"text","value":", flagged "},{"type":"reason","code":"as_of_unknown"},{"type":"text","value":" — a missing date is a caveat, not grounds to withhold a number. The same date anchors the comparable-sales engine: the five-year lookback and the recency weighting are measured from the underwriting date rather than from today, so re-opening a deal months later does not quietly age its comp set out of the window. Without an underwriting date the lookback is measured from the offering memorandum's own report date, and from the run date only when that is unknown. A deal that has not set an underwriting as-of date is otherwise unaffected — the acquisition close date is a modelling input and is never read as a knowledge horizon."}]}]},{"type":"container","kind":"card","attrs":{},"children":[{"type":"heading","level":4,"inline":[{"type":"text","value":"The full ledger"}]},{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"The Sources ledger (linked from every traced figure's tooltip) lists every modeled assumption, its value, and its origin in one table — filter to the ungrounded set to see exactly what's still riding on a default, and export the whole ledger to CSV so every figure in the IC memo is defensible."}]}]}]},"engines":{"title":"Engine architecture","blocks":[{"type":"container","kind":"intro","attrs":{},"children":[{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"Eight deterministic engines run in dependency order. Engine outputs persist as typed payloads; the web app reads them via /deals/{id}/engine_outputs."}]}]},{"type":"container","kind":"card","attrs":{},"children":[{"type":"container","kind":"deflist","attrs":{},"children":[{"type":"list","ordered":false,"attrs":{},"items":[{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Revenue"}]},{"type":"text","value":" Rooms × occupancy × ADR projection + F&B + Other Operated + Resort Fees + Misc."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"F&B"}]},{"type":"text","value":" Per-occupied-room F&B model with food/beverage split; resort fees handled as a separate line."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Expense"}]},{"type":"text","value":" USALI 11th departmental + undistributed + management fee + FF&E reserve + fixed charges → GOP, NOI (institutional), Net Cash Flow."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Capital"}]},{"type":"text","value":" Purchase price + closing costs + renovation budget + working capital → property uses; plus the senior origination fee (owned by the Financing tab) → total capital; Sources & Uses."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Debt"}]},{"type":"text","value":" Senior + PACE tranche stack from analyst-entered terms (fixed or index + spread with floor / cap, amortization or interest-only, IO stub, maturity); monthly amortization schedule; DSCR, debt yield, LTV / LTC; analyst-entered covenant thresholds; refi optionality."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Returns"}]},{"type":"text","value":" Levered + unlevered IRR, equity multiple, Year-1 CoC, terminal value via exit cap × terminal NOI. Handles loss-making (underwater) deals — a negative IRR or sub-1x multiple is reported honestly, not floored or crashed."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Sensitivity"}]},{"type":"text","value":" IRR heatmap across exit cap × RevPAR growth (or other configurable pairs); the IC deck prints this persisted grid, never a synthesized one."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Partnership"}]},{"type":"text","value":" GP / LP waterfall with preferred return, catch-up, promote tiers — run only on the deal's own terms (a partnership document or the analyst's entries); otherwise the engine row is a "},{"type":"code","value":"not_applicable"},{"type":"text","value":" refusal and the Cash Flow statement runs without distribution lines. A deficit period is funded as a dated pro-rata GP/LP capital call (by ownership split) that adds to unreturned capital — the preferred return accrues on it — and is reported as additional contributions; Cash Flow → Partnership → Returns carry one treatment of additional equity."}]}]}]}]},{"type":"container","kind":"card","attrs":{},"children":[{"type":"heading","level":4,"inline":[{"type":"text","value":"Debt is an assumptions workspace"}]},{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"Debt documents are optional. The Financing tab is where the financing is entered, and every core term is an analyst input the model runs on — Fondok does not read the term sheet in this release. Each edit is persisted as an analyst override "},{"type":"badge","source":"analyst_override"},{"type":"text","value":" and re-runs the chain, so the Debt Schedule, DSCR, debt yield, LTV / LTC, Cash Flow and Returns all reflect what was entered. A year whose NOI is negative (a ramp or PIP year) no longer stops the model: its DSCR shows N/A, the debt service its NOI does not cover is reported as that year's shortfall, and the Financing tab names the negative years in one warning. Returns, Cash Flow and Partnership then run on the actual negative cash flow; only a non-positive exit-year NOI stops Returns, because no sale value can be capitalised from it."}]},{"type":"list","ordered":false,"attrs":{},"items":[{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Senior loan (tranche 1)."}]},{"type":"text","value":" Amount (or LTV — either resizes the same loan), rate basis, amortization (0 = interest-only for the full term), an interest-only stub in months before principal begins, and maturity. Fixed prices off the entered coupon; Floating prices off the index assumption plus spread, clamped to an optional floor / cap. Switching basis asks for the term the new basis needs (a spread or a coupon) in the same save. Until an index is entered the floating build-up shows Fondok's flat SOFR assumption and says so — it is not market data."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"PACE loan (tranche 2)."}]},{"type":"text","value":" Funding an amount adds it to Total Debt, LTV, LTC and debt yield immediately. Until a rate is entered the tranche is "},{"type":"em","children":[{"type":"text","value":"terms pending"}]},{"type":"text","value":": it stays out of debt service and DSCR rather than running on an invented rate, and the tab says so next to the input."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Covenants."}]},{"type":"text","value":" Maximum LTV / LTC and minimum DSCR / debt yield are thresholds you enter. There is no default package — a covenant without an entered threshold shows its live Current reading, an “Enter threshold” input, and no pass / fail verdict. Entered thresholds are tested against the modeled Year-1 metrics (LTV / LTC at close)."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Maturity."}]},{"type":"text","value":" The schedule runs to maturity. A take-out before exit is modeled on the Refinance sub-tab; without one the loan balance at the end of the schedule is what the model repays at sale."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Senior origination fee."}]},{"type":"text","value":" The senior loan's origination fee is a "},{"type":"strong","children":[{"type":"text","value":"Fondok seed of 1.50% of the senior loan"}]},{"type":"text","value":" — a platform default, not a figure read from a term sheet or an OM, and it carries the Seed badge "},{"type":"badge","source":"seed"},{"type":"text","value":" until you change it. It is editable on Financing, and Financing is its only owner: the capital engine charges the resolved tranche fee as the Sources & Uses line "},{"type":"strong","children":[{"type":"text","value":"Senior Loan Origination Fee"}]},{"type":"text","value":", and Overview → Capitalization's "},{"type":"strong","children":[{"type":"text","value":"Financing Costs"}]},{"type":"text","value":" reads that same number. Change it on Financing and Sources & Uses, Total Uses, required equity and LTC all move; set it to 0% and the line disappears. One assumption, one number, three labels retired."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Exit fee."}]},{"type":"text","value":" The exit fee is added to the final month's payment on the tranche schedule. It is "},{"type":"em","children":[{"type":"text","value":"not"}]},{"type":"text","value":" carried into Sources & Uses, Cash Flow or Returns in this release, and the row says so — the same treatment as the PACE “terms pending” row."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Missing inputs are inputs."}]},{"type":"text","value":" Wherever a required assumption is absent, the Financing tab renders the input to provide (“Enter rate”, “Enter spread”, “Enter threshold”) with the consequence stated, instead of an unexplained dash."}]}]}]},{"type":"container","kind":"card","attrs":{},"children":[{"type":"heading","level":4,"inline":[{"type":"text","value":"The Returns sensitivity sandbox"}]},{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"Overview → Returns → Sensitivities carries a "},{"type":"strong","children":[{"type":"text","value":"Live Assumptions"}]},{"type":"text","value":" card whose sliders are a sandbox, not an edit. It answers “what would this deal do if…” without changing what the deal "},{"type":"em","children":[{"type":"text","value":"is"}]},{"type":"text","value":"."}]},{"type":"list","ordered":false,"attrs":{},"items":[{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Five assumptions, and only five."}]},{"type":"text","value":" Exit cap rate, RevPAR growth, hold period, LTV and interest rate. The worker applies those keys and ignores everything else in the request, so a sandbox call cannot reach an unrelated engine input."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"The sliders start where the run started."}]},{"type":"text","value":" Each slider's base is the value the returns engine recorded for the canonical run ("},{"type":"code","value":"returns.inputs.assumptions"},{"type":"text","value":"), never a client-side default. A run that did not record one of the five keys shows "},{"type":"em","children":[{"type":"text","value":"Awaiting model run"}]},{"type":"text","value":" in place of the sliders, naming the missing key. The same rule holds for every Returns figure: a headline tile, Return Bridge row or sensitivity cell the engine did not produce reads “—” with the missing engine field named — never 0."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"It runs the whole chain, in memory."}]},{"type":"text","value":" "},{"type":"code","value":"POST /deals/{id}/engines/returns/preview"},{"type":"text","value":" re-runs revenue → F&B → expense → capital → debt → returns on a copy of the deal's canonical inputs. Nothing is written: no "},{"type":"code","value":"engine_outputs"},{"type":"text","value":" row, no run id, no advance of the canonical run, and no change to the deal's "},{"type":"code","value":"field_overrides"},{"type":"text","value":". CAPEX and Financing keep showing the canonical case throughout — that is the point, not a bug."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"The LTV lever is honest."}]},{"type":"text","value":" The Financing tab writes both “Senior Loan Amount” and “LTV” as the same pinned senior principal. When the sandbox flexes LTV, that pin is released "},{"type":"em","children":[{"type":"text","value":"on the in-memory copy only"}]},{"type":"text","value":", so the flexed LTV resizes the senior end-to-end — interest, principal, debt service and DSCR all move with it. Without the release the preview reported returns levered on one loan amount against another loan's debt service, and DSCR never moved at all. A funded PACE or mezzanine tranche keeps its principal: LTV sizes the senior."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Where the sandbox number shows, it says so."}]},{"type":"text","value":" While the sandbox differs from the base case a banner spans every Returns sub-tab and each Returns Summary tile that moved carries a "},{"type":"strong","children":[{"type":"text","value":"Sandbox"}]},{"type":"text","value":" chip. A tile showing a sandbox number does not offer a provenance popover — the trace describes the canonical run, which is not what the tile is showing."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"It survives navigation, and only that."}]},{"type":"text","value":" The sandbox is held in the browser session, per deal. Leaving Returns and coming back keeps it; "},{"type":"strong","children":[{"type":"text","value":"Reset to base case"}]},{"type":"text","value":", opening a different deal, or a fresh canonical run clears it. It is never a URL parameter and is never written to the deal record, so it cannot be shared, bookmarked, or seen by anyone else."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Pricing does not consume it."}]},{"type":"text","value":" The Max Price Solver and the pricing grid are solved on the canonical case, and say so inline while a sandbox is active — a “max price under a hypothetical LTV” is a materially different question from the one the solver answers."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"The slider ranges are the grid's ranges."}]},{"type":"text","value":" The RevPAR-growth slider reads the top of the sensitivity matrix's own axis rather than restating it, so the sliders can never offer less than the grids show."}]}]}]},{"type":"container","kind":"card","attrs":{},"children":[{"type":"heading","level":4,"inline":[{"type":"text","value":"When an engine can't finish"}]},{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"Engines are deterministic and independent, so one can fail without taking down the rest. When one does, the deal shows a clear red banner naming the model, a plain-language reason, and a one-click Re-run — the numbers it feeds read as an explicit error, never as silent “—” dashes that look like missing data. Engines are also hardened against valid-but-extreme inputs (a deeply negative-return scenario, a zero base), so an ugly deal computes rather than crashes."}]}]}]},"pricing":{"title":"Return targets & the Max Price Solver","blocks":[{"type":"container","kind":"intro","attrs":{},"children":[{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"The hurdles a deal must clear are the analyst's, set once on Overview → Investment Profile. Overview → Returns → Pricing reads them from the deal — there is no hidden 15% / 1.80x default anywhere in the pricing path."}]}]},{"type":"container","kind":"card","attrs":{},"children":[{"type":"heading","level":4,"inline":[{"type":"text","value":"The Investment Profile is the source of truth"}]},{"type":"list","ordered":false,"attrs":{},"items":[{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Two pricing hurdles."}]},{"type":"text","value":" "},{"type":"strong","children":[{"type":"text","value":"Target LIRR (levered IRR)"}]},{"type":"text","value":" and "},{"type":"strong","children":[{"type":"text","value":"Target MOIC"}]},{"type":"text","value":" are stored on the deal ("},{"type":"code","value":"target_irr"},{"type":"text","value":" / "},{"type":"code","value":"target_moic"},{"type":"text","value":") as analyst inputs "},{"type":"badge","source":"analyst_override"},{"type":"text","value":". Either may be unset; an unset target renders as “—”. There is one Target LIRR control — no separate returns-profile field."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"The return profile is a preset."}]},{"type":"text","value":" The Target LIRR control carries a preset for each return profile — "},{"type":"strong","children":[{"type":"text","value":"Core 5–10%"}]},{"type":"text","value":", "},{"type":"strong","children":[{"type":"text","value":"Core Plus 7–12%"}]},{"type":"text","value":", "},{"type":"strong","children":[{"type":"text","value":"Value Add 11–17%"}]},{"type":"text","value":", "},{"type":"strong","children":[{"type":"text","value":"Opportunistic 18%+"}]},{"type":"text","value":" (target levered IRR bands; the same four appear on the wizard's Return Profile step). Choosing one stores it as the deal's "},{"type":"code","value":"return_profile"},{"type":"text","value":" tag and writes the band's midpoint (Value Add 11–17% → 14%; an open band such as 18%+ → its floor) as the target — an explicit action, never applied implicitly; nothing auto-fills a target. The analyst can then edit the number; the tag stays as the preset it started from. While no target is set, “Use profile midpoint” writes the current preset's figure. Deals created under the earlier bands keep their stored profile id and simply read the new band."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Benchmark only."}]},{"type":"text","value":" Saving a target never re-runs the model. The Overview's Return benchmark strip compares the calculated levered IRR from the canonical returns run against Target Levered IRR: below the target is "},{"type":"em","children":[{"type":"text","value":"Below target"}]},{"type":"text","value":", at or above it up to 200bp over is "},{"type":"em","children":[{"type":"text","value":"Within target"}]},{"type":"text","value":", and more than 200bp over is "},{"type":"em","children":[{"type":"text","value":"Above target"}]},{"type":"text","value":". It is display only and does not drive any engine."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Target Stabilized Yield on Cost."}]},{"type":"text","value":" The Overview's Yield on cost benchmark compares the analyst's target against the stabilized year's yield on cost — stabilized-year NOI ÷ total capital, both from the model run — and reads "},{"type":"em","children":[{"type":"text","value":"Pass"}]},{"type":"text","value":" at or above the target, "},{"type":"em","children":[{"type":"text","value":"Short"}]},{"type":"text","value":" below it. With no stabilized year or no total capital the actual is “—”, never estimated."}]}]}]},{"type":"container","kind":"card","attrs":{},"children":[{"type":"heading","level":4,"inline":[{"type":"text","value":"Max Price Solver (Overview → Returns → Pricing)"}]},{"type":"list","ordered":false,"attrs":{},"items":[{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"No silent hurdles."}]},{"type":"text","value":" "},{"type":"code","value":"POST /analysis/{id}/pricing/max-price"},{"type":"text","value":" reads the deal's targets when the request omits them. If neither the deal nor the request carries at least one target, the worker answers 422 — “No return target set — set Target Levered IRR / Target MOIC on the Investment Profile or pass them explicitly” — and the Pricing block shows that message with a link to the Investment Profile and no numbers."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Lower-of rule."}]},{"type":"text","value":" Each hurdle is solved independently by bisecting on purchase price (loan amount held fixed, equity flexes; 50%–200% of the current basis; ≤ 40 iterations). Max Price is the lower of the IRR-solved and MOIC-solved prices and the "},{"type":"em","children":[{"type":"text","value":"binding constraint"}]},{"type":"text","value":" is named (IRR, MOIC, or both when they land within $50K). With a single target set, that hurdle governs on its own."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Unreachable hurdles stay unreachable."}]},{"type":"text","value":" A hurdle that no price down to 50% of the basis can clear reports “no price clears the hurdles” (Max Price “—”); one that clears even at 2× the basis reports “≥ 2× basis”. The bracket endpoint is never shown as a price."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Pricing sensitivity grid."}]},{"type":"text","value":" "},{"type":"code","value":"POST /analysis/{id}/pricing/max-price-grid"},{"type":"text","value":" re-runs the solver per cell over exit cap rate (base ± 100bp in 50bp steps) × RevPAR growth (base ± 2pp in 1pp steps), at most 25 cells. Each cell shows the maximum purchase price clearing both hurdles with its binding constraint. The growth axis is the deal's "},{"type":"code","value":"revpar_growth"},{"type":"text","value":" assumption — the same lever the Sensitivities grids flex and the same one the P&L assumption names — so both places call it RevPAR growth. Here it also re-tilts the model's canonical NOI series relative to the base growth assumption: year 1 is unchanged, later years and the exit NOI move, so the base cell reproduces the headline solve exactly."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"The Returns sandbox is not applied."}]},{"type":"text","value":" Both pricing blocks call the solver with no overrides, so an active Live Assumptions sandbox does not reach them. While one is on, each block says so inline rather than quietly answering a different question. Reset the sandbox on Sensitivities to compare like for like."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Exports."}]},{"type":"text","value":" "},{"type":"code","value":"export/live_payload.py"},{"type":"text","value":" resolves the deal's targets through the same "},{"type":"code","value":"_deal_return_targets"},{"type":"text","value":" read the pricing routes use; the Excel Pricing Sensitivity sheet and memo Max-Price Findings carry no solver output without a target (they state “Pricing to target not available: no return target set on this deal”), and the deck's heat-map is the persisted "},{"type":"code","value":"sensitivity"},{"type":"text","value":" engine row or a stated reason. No export module holds a default hurdle, a fixture, or a demo path."}]}]}]},{"type":"container","kind":"card","attrs":{},"children":[{"type":"heading","level":4,"inline":[{"type":"text","value":"Asking vs Bidding price (Overview KPIs)"}]},{"type":"list","ordered":false,"attrs":{},"items":[{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Two comparable sets."}]},{"type":"text","value":" On an acquisition deal the Overview KPI area shows the same metrics twice — Purchase Price, Total Capitalization, Renovation, Stabilized NOI, Levered and Unlevered IRR — once at the "},{"type":"em","children":[{"type":"text","value":"asking"}]},{"type":"text","value":" price and once at the "},{"type":"em","children":[{"type":"text","value":"bidding"}]},{"type":"text","value":" price, from "},{"type":"code","value":"GET /analysis/{id}/pricing/asking-vs-bid"},{"type":"text","value":" (read-only; nothing is persisted)."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Asking price."}]},{"type":"text","value":" The OM's extracted asking price ("},{"type":"code","value":"asking_price.headline_price_usd"},{"type":"text","value":", as extracted, before any analyst override). With no OM price the modeled purchase price stands in and is labelled with its source (deal record, analyst override or seed). When the asking price is the modeled price the set shows the canonical Base Case run; otherwise the deal is re-priced at the asking price with everything else held."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Bidding price — solved backward from Target LIRR."}]},{"type":"text","value":" The bid is the existing Max Price Solver run on the IRR hurdle alone: bisect the purchase price until the returns engine's levered IRR equals the deal's Target LIRR (50%–200% of the modeled price, 5bp / $50K tolerance). As in the solver, the loan amount is held, equity absorbs the price difference, and closing costs, renovation and the NOI path are unchanged — so Total Capitalization moves one-for-one with price and Renovation / Stabilized NOI read the same in both sets. Each set's IRRs are a fresh returns-engine run at that price."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"No target, no bid."}]},{"type":"text","value":" With no Target LIRR on the Investment Profile the Bidding set reads “Set Target LIRR to solve” and shows no numbers; a target outside the solver's bracket reports that instead of a bracket-end price."}]}]}]},{"type":"container","kind":"card","attrs":{},"children":[{"type":"heading","level":4,"inline":[{"type":"text","value":"Investment Bridge"}]},{"type":"list","ordered":false,"attrs":{},"items":[{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Equity invested → equity returned."}]},{"type":"text","value":" The Investment Bridge tab (immediately before Scenario Analysis) is a waterfall from the equity funded at close ("},{"type":"code","value":"−returns.cash_flows[0]"},{"type":"text","value":" = "},{"type":"code","value":"capital.equity_amount"},{"type":"text","value":") to the total cash returned to equity ("},{"type":"code","value":"Σ returns.cash_flows[1:]"},{"type":"text","value":"), deal-level before GP/LP allocation, read from the Base Case run via "},{"type":"code","value":"GET /deals/{id}/engines/investment-bridge"},{"type":"text","value":"."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Five legs, each an engine field."}]},{"type":"text","value":" "},{"type":"em","children":[{"type":"text","value":"Acquisition"}]},{"type":"text","value":" = −every Sources & Uses line except Renovation and the senior loan fee (purchase price, closing costs, working capital, reserves…). "},{"type":"em","children":[{"type":"text","value":"Renovation / PIP"}]},{"type":"text","value":" = −the Renovation use line (contingency included). "},{"type":"em","children":[{"type":"text","value":"Operations"}]},{"type":"text","value":" = Σ "},{"type":"code","value":"returns.noi_by_year"},{"type":"text","value":" over the hold. "},{"type":"em","children":[{"type":"text","value":"Financing"}]},{"type":"text","value":" = loan proceeds − loan origination fee − Σ debt service + any refinance cash-out − the loan payoff at exit, using the exact debt-service series, exit balance and refi cash-out the returns engine consumed. "},{"type":"em","children":[{"type":"text","value":"Exit"}]},{"type":"text","value":" = gross sale price − selling costs − transfer tax."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"It foots by construction."}]},{"type":"text","value":" Because equity = total uses − debt and each levered cash flow = NOI − debt service (+ refi, + net sale less payoff at exit), equity invested plus the five legs equals equity returned exactly. The tab states the check. A leg the run cannot support shows “—” with the reason (never a zero bar) and the bridge then says it does not foot."}]}]}]}]},"ic-memo":{"title":"IC Memo — diligence flags and the decision","blocks":[{"type":"container","kind":"intro","attrs":{},"children":[{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"How broker-vs-T-12 variance flags reach the committee, what an 'NOI impact' on a flag means, how diligence status is kept, and why the IC recommendation is a recorded decision rather than a model inference."}]}]},{"type":"container","kind":"card","attrs":{},"children":[{"type":"list","ordered":false,"attrs":{},"items":[{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"One flag per business concept."}]},{"type":"text","value":" The extractor can emit the same broker line under several field paths (for example "},{"type":"code","value":"broker_proforma.rooms_revenue_usd"},{"type":"text","value":", "},{"type":"code","value":"broker.rooms_revenue"},{"type":"text","value":" and a flat "},{"type":"code","value":"rooms_revenue_usd"},{"type":"text","value":"). The variance report groups those by their normalized concept — rooms revenue, F&B revenue, total revenue, occupancy, ADR, RevPAR, GOP, NOI, and each expense line — and the IC memo lists one item per concept with a business-readable title (“Rooms revenue — broker overstates T-12 by 5.3%”). The consolidated severity is the highest severity across the merged rows. The normalized keys, every raw field path, its own broker and T-12 values, and the USALI rule ids stay available under "},{"type":"em","children":[{"type":"text","value":"Technical detail"}]},{"type":"text","value":" on each item and in the Technical detail column of the exported Variance sheet."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"“Estimated NOI impact” only when the delta is an NOI delta."}]},{"type":"text","value":" A dollar NOI impact is shown only for the NOI and GOP concepts, where the broker-vs-T-12 delta "},{"type":"em","children":[{"type":"text","value":"is"}]},{"type":"text","value":" the NOI difference. A revenue-line, KPI, or expense-line variance shows “Revenue-line variance — NOI impact not estimated” (or the expense / market-forecast equivalent) rather than a dollar figure — Fondok does not translate a revenue or expense delta into NOI without a flow-through assumption, and it never presents a revenue delta as if it were NOI."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Diligence status is persisted per concept."}]},{"type":"text","value":" Resolve, Accept variance and Reopen are recorded on the deal ("},{"type":"code","value":"memo_diligence"},{"type":"text","value":", keyed by concept), so the IC-readiness checklist reads the same open / resolved status after a reload, and the Excel export's Variance sheet prints the same status in its Diligence column. A concept with no recorded status is Open. Status is analyst-recorded only — Fondok never auto-resolves a flag."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"The IC recommendation is a decision, not an inference."}]},{"type":"text","value":" The Model Assessment card shows the model's own read of the Base Case (Clears Hurdles / Clears with Conditions / Below Hurdles, with the inferred verdict labelled as the model's). The IC recommendation reads "},{"type":"em","children":[{"type":"text","value":"Pending analyst decision"}]},{"type":"text","value":" until the analyst selects Proceed, Proceed with Conditions or Do Not Proceed "},{"type":"em","children":[{"type":"text","value":"and"}]},{"type":"text","value":" confirms it. Only the confirmed verdict is written into the memo's Recommendation section and the export header; a selected-but-unconfirmed verdict, or a verdict recorded before confirmation existed, still reads Pending analyst decision, under the reason code "},{"type":"reason","code":"awaiting_analyst"},{"type":"text","value":". Confirmation is part of the IC-readiness checklist."}]}]}]},{"type":"container","kind":"card","attrs":{},"children":[{"type":"heading","level":4,"inline":[{"type":"text","value":"What a variance flag compares — and what it refuses to"}]},{"type":"list","ordered":false,"attrs":{},"items":[{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Only the broker's own claim is the “broker” side."}]},{"type":"text","value":" A row counts as the broker's claim about the subject only when it comes from the OM / broker materials under a claim path ("},{"type":"code","value":"broker_proforma.*"},{"type":"text","value":", "},{"type":"code","value":"broker.*"},{"type":"text","value":", "},{"type":"code","value":"ttm_summary_per_om.*"},{"type":"text","value":", "},{"type":"code","value":"ttm_performance.subject.*"},{"type":"text","value":"). A line from a T-12 or P&L document is an actual, never a broker figure, even when the extractor labelled it with an OM-style path; a subject or submarket reading from an STR / CoStar report is STR-reported performance, not the broker's claim; a competitive-set stat ("},{"type":"code","value":"ttm_performance.segment.*"},{"type":"text","value":"), the OM's historical-year block ("},{"type":"code","value":"p_and_l_usali.2021.*"},{"type":"text","value":"), and lines from CBRE, CapEx, insurance or property-information documents are none of these either. Rows excluded for one of these reasons are still listed under Technical detail with the reason and their source document, each carrying "},{"type":"reason","code":"basis_excluded"},{"type":"text","value":" — the report says what it left out."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Units are normalised before comparing."}]},{"type":"text","value":" Occupancy and other ratio lines are compared as fractions (an extracted 83 or 83% reads as 0.83; the conversion is noted on the row); currency is compared in whole dollars (a “$000” unit is scaled). A value whose unit cannot be established — an occupancy above 100, for example — is not compared at all ("},{"type":"reason","code":"unit_unknown"},{"type":"text","value":"), and the Technical detail says why. A figure whose "},{"type":"em","children":[{"type":"text","value":"path"}]},{"type":"text","value":" declares a unit the concept does not carry is refused under the same code: an OM proforma's %-of-revenue column ("},{"type":"code","value":"broker_proforma.rooms_revenue_pct"},{"type":"text","value":") read against a dollar T-12 line is rejected before any comparison, so it never produces a variance percentage. Fondok does not reconstruct dollars from a percent claim — the denominator would itself be an unverified broker figure."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Annual against annual."}]},{"type":"text","value":" The T-12 side is the document's annual / trailing-twelve-month line (annual rooms revenue, gross operating profit, net operating income), never a monthly or quarterly slice, and the T-12 is preferred over a supporting P&L. If no annual actual exists for a concept there is no flag — Fondok never compares a month against a year, and the report names the concept it could not compare with "},{"type":"reason","code":"period_mismatch"},{"type":"text","value":" or "},{"type":"reason","code":"no_source"},{"type":"text","value":"."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Plausibility guard."}]},{"type":"text","value":" As a last line of defence, a pair of figures more than 300% apart is reported as “Basis mismatch — needs review” ("},{"type":"reason","code":"basis_mismatch"},{"type":"text","value":") with both raw figures and no severity, instead of a Critical variance: two numbers that far apart are on different bases, not evidence of a broker overstatement."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"NOI is compared like-for-like across the FF&E reserve."}]},{"type":"text","value":" A broker proforma states NOI "},{"type":"em","children":[{"type":"text","value":"before"}]},{"type":"text","value":" the FF&E replacement reserve (USALI “EBITDA”), while the T-12 line Fondok normalises to is "},{"type":"em","children":[{"type":"text","value":"after"}]},{"type":"text","value":" it (USALI “EBITDA Less Replacement Reserve”). Comparing the two reports the reserve as if it were a broker overstatement. So when the actuals document states its own before-reserve line, the broker's NOI claim is compared against that one, and the row says which figure it used; when the document states only the after-reserve line, the pair is refused as “Basis mismatch — needs review” ("},{"type":"reason","code":"basis_mismatch"},{"type":"text","value":") with both figures and no severity. The before-reserve figure is only ever read from the document — never reconstructed by adding the reserve back."}]}]}]}]},"reasons":{"title":"What a dash means","blocks":[{"type":"container","kind":"intro","attrs":{},"children":[{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"Where Fondok cannot produce a figure it shows a dash — never a placeholder, a zero, or a number carried over from a prototype. Every such refusal resolves to one of the reason codes below. They are one shared vocabulary (packages/schemas-py/fondok_schemas/reasons.py, mirrored in TypeScript) and this table is rendered from that module, so it cannot drift from what the code does."}]}]},{"type":"container","kind":"card","attrs":{"flush":"true"},"children":[{"type":"slot","name":"reason-code-table-engineering"}]},{"type":"container","kind":"card","attrs":{},"children":[{"type":"heading","level":4,"inline":[{"type":"text","value":"How to read a dash"}]},{"type":"list","ordered":false,"attrs":{},"items":[{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"One glyph, many reasons."}]},{"type":"text","value":" Today every code renders the same “—”; the code is what distinguishes them. It travels on the value's provenance record ("},{"type":"code","value":"reason"},{"type":"text","value":", alongside the source and formula that “Hover any number to trace it” in Section 3 describes) as each tab and export adopts the vocabulary."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Where it lands on the Data Key."}]},{"type":"text","value":" "},{"type":"code","value":"needs_review"},{"type":"text","value":", "},{"type":"code","value":"basis_mismatch"},{"type":"text","value":", "},{"type":"code","value":"period_mismatch"},{"type":"text","value":" and "},{"type":"code","value":"unit_unknown"},{"type":"text","value":" describe a figure that exists but cannot be trusted or compared, so they read as "},{"type":"em","children":[{"type":"text","value":"Needs review"}]},{"type":"text","value":". Every other code means the figure is not there yet and reads as "},{"type":"em","children":[{"type":"text","value":"Awaiting data"}]},{"type":"text","value":"."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"A dash is not an error."}]},{"type":"text","value":" An engine that could not finish shows the red banner described in Section 4, with a Re-run. A dash is the model declining to invent a number it has no grounds for — the code says which grounds are missing."}]}]}]},{"type":"container","kind":"card","attrs":{},"children":[{"type":"heading","level":4,"inline":[{"type":"text","value":"Structure edits change how a statement reads, never what it computes"}]},{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"On P&L → Historical P&L, "},{"type":"strong","children":[{"type":"text","value":"Customize structure"}]},{"type":"text","value":" lets an analyst relabel a line, split one line into presentation children that must reconcile to the locked parent, reorder lines within their section, hide a line, and add an "},{"type":"strong","children":[{"type":"text","value":"analyst line"}]},{"type":"text","value":" of their own. All five are "},{"type":"strong","children":[{"type":"text","value":"presentation"}]},{"type":"text","value":": the canonical value behind each row, the document it was read from and the Data Key state it carries are untouched by any of them, and a reordered row keeps its own lineage because the layout stores row identities, not values. An analyst line is marked as an assumption and carries an "},{"type":"em","children":[{"type":"text","value":"Analyst line"}]},{"type":"text","value":" chip — it is entered here, is read from no document, and no engine reads it."}]},{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"The layout is stored "},{"type":"strong","children":[{"type":"text","value":"on the deal"}]},{"type":"text","value":" ("},{"type":"code","value":"field_overrides.worksheet_layout"},{"type":"text","value":"), not in the browser, so every reviewer who opens the deal reads the statement as the analyst arranged it — a reordered statement is a deal artifact an IC reviewer must see, not a per-device preference. It is the one "},{"type":"code","value":"field_overrides"},{"type":"text","value":" key the engines never read: the worker skips it explicitly when it routes overrides into engine input, so a relabel, split, reorder, hide or added line cannot move a modeled number. If a layout edit fails to save, the worksheet says so and offers a retry rather than letting the arrangement look saved. "},{"type":"strong","children":[{"type":"text","value":"Reset layout"}]},{"type":"text","value":" drops every structure edit and restores the canonical statement."}]}]}]},"concept-registry":{"title":"Concept registry","blocks":[{"type":"container","kind":"intro","attrs":{},"children":[{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"Every P&L line, operating statistic, OM figure, debt term and market metric Fondok names is defined once, in a registry the worker validates at boot and the web app is generated from. Registry v"},{"type":"slot","name":"registry-version"},{"type":"text","value":" · "},{"type":"slot","name":"registry-count"},{"type":"text","value":" concepts on this table."}]}]},{"type":"container","kind":"card","attrs":{},"children":[{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"The same line reaches Fondok under many names — an extractor may emit "},{"type":"code","value":"p_and_l_usali.gross_operating_profit"},{"type":"text","value":", "},{"type":"code","value":"gop_usd"},{"type":"text","value":" or "},{"type":"code","value":"ttm_summary_per_om.gop_usd"},{"type":"text","value":" for one GOP figure — and until now each screen and engine kept its own list of those names. The registry ("},{"type":"code","value":"apps/worker/app/ontology/concepts.yaml"},{"type":"text","value":") holds one entry per concept: its USALI line, unit, sign and period, the identity it must satisfy (GOP = Total Revenue − Departmental − Undistributed), the USALI rules that test it, the engines that consume it, and its aliases per document type — each alias tagged with the basis it carries (a T-12 line is an "},{"type":"em","children":[{"type":"text","value":"actual"}]},{"type":"text","value":"; a "},{"type":"code","value":"broker_proforma.*"},{"type":"text","value":" line is the "},{"type":"em","children":[{"type":"text","value":"broker's claim"}]},{"type":"text","value":"; the OM's historical-year block and comp-set stats are neither) and, where the path says so, its period. The worker validates the registry when it starts (duplicate aliases, unknown rule ids or engines, an identity naming an unknown concept all fail the load) and reports the version on "},{"type":"code","value":"/health"},{"type":"text","value":" as "},{"type":"code","value":"ontology_version"},{"type":"text","value":"; "},{"type":"code","value":"GET /ontology/concepts"},{"type":"text","value":" serves it, and this page and the web app read a generated copy that CI refuses to let drift. Resolution is deterministic: an exact path listed for the document type wins, then a path listed for any document, then a unit-suffix-stripped match, then the field's last segment against a bare alias — a monthly, quarterly or year-to-date slice is never served as an annual figure, and a request for the broker's claim never returns the OM's history. The unit-suffix-stripped tier now "},{"type":"em","children":[{"type":"text","value":"refuses"}]},{"type":"text","value":" rather than reinterprets: it still lets a "},{"type":"code","value":"_usd"},{"type":"text","value":" or bare sibling find its concept, but a path that declares a unit the concept does not carry — a "},{"type":"code","value":"_pct"},{"type":"text","value":" column against a dollar line — resolves to "},{"type":"reason","code":"unit_unknown"},{"type":"text","value":" instead of being read under the concept's unit. A path that declares no unit at all is unaffected. The dash reasons in Section 7 are drawn from this same registry. Today the registry is the declared vocabulary and the drift gate; the engines, the USALI scorer, the variance report and the worksheet are re-wired onto it in the next phase, and their behaviour on the live system is unchanged until then."}]}]},{"type":"container","kind":"card","attrs":{},"children":[{"type":"heading","level":4,"inline":[{"type":"text","value":"Concepts (generated from the registry)"}]},{"type":"slot","name":"concept-registry-table"}]}]},"lineage":{"title":"Every number traces back","blocks":[{"type":"container","kind":"intro","attrs":{},"children":[{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"Pick any headline number on a deal and Fondok can show you the chain that produced it, one step at a time, down to the page of the document it was read from — or state, in the vocabulary of Section 7, exactly why the chain stops short."}]}]},{"type":"container","kind":"card","attrs":{},"children":[{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"The pieces already existed separately: each engine emits a per-value trace (the formula, its named inputs, and a pointer at whichever other value fed it — Section 3's “hover any number”), the assumption loader records which source produced every input, each extracted field carries the page it was read from, and the IC memo carries its citations. "},{"type":"code","value":"GET /deals/{id}/lineage"},{"type":"text","value":" joins them into one graph and serves it for the same run every tab is pinned to, so the chain always describes the numbers on screen rather than a newer or older model run. Each link in that graph also says how it was established: "},{"type":"strong","children":[{"type":"text","value":"asserted"}]},{"type":"text","value":" when the engine that computed the value named the assumption or the upstream value itself, and "},{"type":"strong","children":[{"type":"text","value":"inferred"}]},{"type":"text","value":" when Fondok had to derive the connection from the engine dependency graph instead — a genuine link either way, but only the asserted one is the engine's own claim, and every deal's chain carries the count of each."}]}]},{"type":"container","kind":"card","attrs":{},"children":[{"type":"heading","level":4,"inline":[{"type":"text","value":"The walk"}]},{"type":"container","kind":"chain","attrs":{},"children":[{"type":"list","ordered":true,"attrs":{},"items":[{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"KPI"}]},{"type":"text","value":" — a headline number — levered IRR, unlevered IRR, equity multiple, Year-1 cash-on-cash, minimum DSCR, Year-1 NOI. These are the roots you can start from."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Engine value"}]},{"type":"text","value":" — the modeled value behind it, and each modeled value behind that — IRR to the cash flows, cash flows to NOI and debt service, NOI to GOP, GOP to total revenue, revenue to rooms revenue."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Assumption"}]},{"type":"text","value":" — the underwriting input the calculation rests on — starting occupancy, starting ADR, exit cap rate, LTV — carrying the source that produced it."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Extracted field"}]},{"type":"text","value":" — the exact field on the exact extraction that supplied the assumption, with the concept it resolved to (Section 8) and the basis and period it carries."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Document → page"}]},{"type":"text","value":" — the uploaded document, and the page the number sits on. This is where a walk that closes ends."}]}]}]},{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"Three chains end deliberately short of a page, and each says so rather than looking grounded. An "},{"type":"strong","children":[{"type":"text","value":"analyst override"}]},{"type":"text","value":" ends at the override, carrying the justification note the analyst saved with it. A "},{"type":"strong","children":[{"type":"text","value":"seed"}]},{"type":"text","value":" — a platform default no document on the deal supports — ends at the seed. A "},{"type":"strong","children":[{"type":"text","value":"benchmark"}]},{"type":"text","value":" — CBRE Horizons, the HOST default set, your own portfolio P&L, an STR feed — ends at the benchmark, and continues to a page only when the benchmark itself arrived as an uploaded document."}]}]},{"type":"container","kind":"card","attrs":{},"children":[{"type":"heading","level":4,"inline":[{"type":"text","value":"What each step is"}]},{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"Every step in a chain is one of eleven kinds, and its identifier says which — so a link into the chain is stable and points at exactly one thing."}]},{"type":"table","attrs":{},"head":[[{"type":"text","value":"Step"}],[{"type":"text","value":"Identifier"}],[{"type":"text","value":"What it is"}]],"rows":[[[{"type":"strong","children":[{"type":"text","value":"KPI"}]}],[{"type":"code","value":"kpi:"}],[{"type":"text","value":"A headline number a tab renders — the root of a chain."}]],[[{"type":"strong","children":[{"type":"text","value":"Engine value"}]}],[{"type":"code","value":"engine:"}],[{"type":"text","value":"One modeled value in an engine’s output, with the formula and inputs that produced it."}]],[[{"type":"strong","children":[{"type":"text","value":"Assumption"}]}],[{"type":"code","value":"assumption:"}],[{"type":"text","value":"A canonical underwriting input, carrying the source that set it."}]],[[{"type":"strong","children":[{"type":"text","value":"Statement line"}]}],[{"type":"code","value":"line:"}],[{"type":"text","value":"A USALI-normalized statement line. Reserved — the walk gains this step when normalized spreads are stored per run."}]],[[{"type":"strong","children":[{"type":"text","value":"Extracted field"}]}],[{"type":"code","value":"field:"}],[{"type":"text","value":"One field on one extraction, with its concept, basis and period."}]],[[{"type":"strong","children":[{"type":"text","value":"Document"}]}],[{"type":"code","value":"doc:"}],[{"type":"text","value":"An uploaded document on the deal."}]],[[{"type":"strong","children":[{"type":"text","value":"Page"}]}],[{"type":"code","value":"page:"}],[{"type":"text","value":"The page of that document the value was read from."}]],[[{"type":"strong","children":[{"type":"text","value":"Override"}]}],[{"type":"code","value":"override:"}],[{"type":"text","value":"An analyst override, carrying the justification note. Terminal."}]],[[{"type":"strong","children":[{"type":"text","value":"Seed"}]}],[{"type":"code","value":"seed:"}],[{"type":"text","value":"A platform default no document supports. Terminal, with its reason."}]],[[{"type":"strong","children":[{"type":"text","value":"Benchmark"}]}],[{"type":"code","value":"benchmark:"}],[{"type":"text","value":"A benchmark or market feed — CBRE Horizons, HOST, your portfolio P&L, STR."}]],[[{"type":"strong","children":[{"type":"text","value":"Memo section"}]}],[{"type":"code","value":"memo:"}],[{"type":"text","value":"An IC-memo section, linked from the document and page it cites."}]]]}]},{"type":"container","kind":"card","attrs":{},"children":[{"type":"heading","level":4,"inline":[{"type":"text","value":"A link that does not close states its reason"}]},{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"Anything the walk cannot take all the way to a page is reported, never dropped: each unresolved link names the step it broke on and carries a reason code from the Section 7 vocabulary — "},{"type":"code","value":"no_document"},{"type":"text","value":" when nothing on the deal could ground it, "},{"type":"code","value":"no_source"},{"type":"text","value":" when documents exist but none of their fields resolves to the concept, "},{"type":"code","value":"str_unavailable"},{"type":"text","value":" when a requested feed did not populate. An empty list means every root reached a document page. It never means the search stopped early."}]}]},{"type":"container","kind":"card","attrs":{},"children":[{"type":"heading","level":4,"inline":[{"type":"text","value":"What “stale” means"}]},{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"A chain describes one engine run, so it is only as current as that run's inputs. When a document is uploaded — or the deal record edited, or a document the run relied on deleted — "},{"type":"em","children":[{"type":"text","value":"after"}]},{"type":"text","value":" the run started, the chain is marked "},{"type":"strong","children":[{"type":"text","value":"stale"}]},{"type":"text","value":". Stale does not mean wrong and it does not hide the chain: the evidence shown is still exactly what produced the numbers you are looking at. It means the deal has moved since, and re-running the model will produce a different chain. It is the same condition Section 7's "},{"type":"code","value":"stale_run"},{"type":"text","value":" describes, surfaced on the evidence rather than on a single figure."}]}]}]},"regression-baselines":{"title":"Telling an intended change from a calculation drift","blocks":[{"type":"container","kind":"intro","attrs":{},"children":[{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"Every model run is kept, so the numbers a deal showed before a change can always be put next to the numbers it shows after — field by field, with the source of each side."}]}]},{"type":"container","kind":"card","attrs":{"testid":"methodology-regression-baselines"},"children":[{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"Each engine run writes a new row per engine and never overwrites an earlier one; only deleting the deal removes them. The "},{"type":"strong","children":[{"type":"text","value":"Compare runs"}]},{"type":"text","value":" panel at the top of a deal's Activity tab picks a "},{"type":"strong","children":[{"type":"text","value":"baseline"}]},{"type":"text","value":" — by default the newest complete run of the full engine chain that finished before a date you choose, skipping every run recorded as a scenario run other than Base — each scenario run leaves an audit entry naming its scenario, so older scenario runs are recognised too, not only the latest (the Base scenario's runs, normally what every tab serves, stay eligible); when no run finished before the default date — every run on a duplicated or newly created deal — the panel falls back to the deal's newest complete run before the current one and says so beneath the pickers, while a date you choose yourself never falls back — and a "},{"type":"strong","children":[{"type":"text","value":"head"}]},{"type":"text","value":" run (by default the run every tab is serving now). It lists each headline output that moved, grouped by engine: occupancy, ADR, RevPAR, revenue, departmental and undistributed expenses, management fee, FF&E reserve, GOP and NOI before and after the reserve for each year; purchase price, total capitalization, equity and renovation; loan amount and DSCR by year; levered and unlevered IRR, equity multiple, exit value and exit NOI; the stabilization block; and LP and GP IRR. Each row shows both values, the absolute change and the percentage change, with the engine's recorded source and formula for each side. A percentage change on a zero baseline, or a field one run does not carry, shows a dash and says why. The same table exports to Excel. Comparing never re-runs or edits the model."}]},{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"The repository also keeps a fixed reference: the golden reference fixture's full engine outputs as of 16 October 2026 ("},{"type":"code","value":"evals/baselines/kimpton-golden-2026-10-16.json"},{"type":"text","value":"). "},{"type":"code","value":"scripts/compare_golden_baseline.py"},{"type":"text","value":" re-runs that fixture on the current code and prints the same field-level diff, so every change to a calculation can be checked against what it was expected to move."}]}]}]}};
